struct FemFrequencyScheduleCursor<'a> {
    schedule: &'a SolveSchedule,
    checkpoint: &'a mut FemRunCheckpoint,
    tasks: Vec<SolveWorkItem>,
}

impl<'a> FemFrequencyScheduleCursor<'a> {
    fn begin(
        schedule: &'a SolveSchedule,
        checkpoint: &'a mut FemRunCheckpoint,
        frequency_count: usize,
        source_count: usize,
    ) -> Result<Self> {
        let tasks = frequency_tasks(schedule, frequency_count, source_count)?;
        match checkpoint.status {
            super::run_state::FemRunStatus::Pending => checkpoint.start(schedule)?,
            super::run_state::FemRunStatus::Running | super::run_state::FemRunStatus::Cancelled => {
                let cursor = checkpoint.next_task_index;
                checkpoint.resume(schedule, cursor)?;
            }
            status => anyhow::bail!("cannot resume FEM schedule in {status:?} state"),
        }
        Ok(Self {
            schedule,
            checkpoint,
            tasks,
        })
    }

    fn poll_cancellation(&mut self, cancellation: &FemRunCancellation) -> Result<()> {
        if self
            .checkpoint
            .poll_cancellation(self.schedule, cancellation)?
        {
            let reason = cancellation
                .first_error()
                .unwrap_or_else(|| "cancelled cooperatively".into());
            anyhow::bail!("FEM run cancelled: {reason}");
        }
        Ok(())
    }

    fn source_blocks_for_frequency(&self, frequency_index: usize) -> Result<Vec<(usize, usize)>> {
        let blocks: Vec<_> = self
            .tasks
            .iter()
            .filter(|task| task.frequency_index == frequency_index)
            .map(|task| (task.source_start, task.source_count))
            .collect();
        anyhow::ensure!(
            !blocks.is_empty(),
            "FEM schedule has no source blocks for frequency {frequency_index}"
        );

        let mut expected_start = 0;
        for &(source_start, source_count) in &blocks {
            anyhow::ensure!(
                source_count > 0 && source_start == expected_start,
                "FEM schedule source blocks for frequency {frequency_index} must be contiguous"
            );
            expected_start += source_count;
        }
        Ok(blocks)
    }

    fn commit_frequency(&mut self, frequency_index: usize) -> Result<()> {
        let Some(group_start) = self
            .tasks
            .iter()
            .position(|task| task.frequency_index == frequency_index)
        else {
            anyhow::bail!("FEM schedule has no task group for frequency {frequency_index}");
        };
        let group_end = self.tasks[group_start..]
            .iter()
            .position(|task| task.frequency_index != frequency_index)
            .map_or(self.tasks.len(), |offset| group_start + offset);
        let next_task_index = self.checkpoint.next_task_index;

        if group_end <= next_task_index {
            // Replaying a committed prefix reconstructs previous-frequency
            // warm starts and recycled subspaces without double-committing it.
            return Ok(());
        }
        if group_start != next_task_index {
            anyhow::bail!(
                "FEM schedule cursor skipped frequency {frequency_index}; next task is {next_task_index}"
            );
        }

        // The production solver evaluates all sources in one frequency
        // transaction. Commit every admitted source block only after that
        // transaction has completed, preserving the planner's source-block
        // topology without publishing a partially solved frequency.
        for (task_index, task) in self.tasks[group_start..group_end]
            .iter()
            .copied()
            .enumerate()
        {
            self.checkpoint.commit_next_task(
                self.schedule,
                group_start + task_index,
                task,
                task.estimated_bytes,
            )?;
        }
        Ok(())
    }

    fn complete(mut self, cancellation: Option<&FemRunCancellation>) -> Result<()> {
        if let Some(cancellation) = cancellation {
            self.poll_cancellation(cancellation)?;
        }
        self.checkpoint.complete(self.schedule)?;
        Ok(())
    }
}

fn frequency_tasks(
    schedule: &SolveSchedule,
    frequency_count: usize,
    source_total: usize,
) -> Result<Vec<SolveWorkItem>> {
    anyhow::ensure!(frequency_count > 0, "FEM schedule requires frequencies");
    anyhow::ensure!(source_total > 0, "FEM schedule requires sources");
    anyhow::ensure!(
        schedule.lanes.len() == 1,
        "FEM run requires one schedule lane"
    );
    let lane = &schedule.lanes[0];
    anyhow::ensure!(
        lane.lane_index == 0 && lane.candidate_indices == [0],
        "FEM run schedule must contain candidate zero on lane zero"
    );
    anyhow::ensure!(
        schedule.task_count == lane.tasks.len(),
        "FEM run schedule task count must match its lane topology"
    );

    let mut expected_frequency = 0;
    let mut expected_source_start = 0;
    for task in &lane.tasks {
        anyhow::ensure!(
            task.candidate_index == 0 && task.frequency_index == expected_frequency,
            "FEM run schedule tasks must be grouped by frequency"
        );
        anyhow::ensure!(
            task.source_count > 0
                && task.source_start == expected_source_start
                && expected_source_start < source_total
                && task.source_count <= source_total - expected_source_start,
            "FEM run schedule source blocks must be contiguous and cover each frequency"
        );

        expected_source_start += task.source_count;
        if expected_source_start == source_total {
            expected_frequency += 1;
            expected_source_start = 0;
        }
    }

    anyhow::ensure!(
        expected_frequency == frequency_count && expected_source_start == 0,
        "FEM run schedule must cover every source for every frequency"
    );
    Ok(lane.tasks.clone())
}

#[cfg(test)]
mod schedule_tests {
    use super::*;
    use crate::fem_runner::scheduler::{ResourceBudget, WorkloadShape, plan_solve_schedule};

    fn schedule() -> SolveSchedule {
        plan_solve_schedule(
            WorkloadShape {
                candidate_count: 1,
                frequency_count: 3,
                source_count: 2,
                rhs_block_size: 2,
            },
            ResourceBudget {
                lane_limit: 1,
                memory_budget_bytes: 1_000,
                shared_bytes: 100,
                per_lane_bytes: 100,
                per_frequency_bytes: 20,
                per_rhs_bytes: 30,
                per_output_bytes: 10,
            },
        )
        .unwrap()
    }

    #[test]
    fn frequency_adapter_requires_one_full_source_batch_per_frequency() {
        let schedule = schedule();
        let tasks = frequency_tasks(&schedule, 3, 2).unwrap();
        assert_eq!(tasks.len(), 3);
        assert!(tasks.iter().enumerate().all(|(index, task)| {
            task.candidate_index == 0
                && task.frequency_index == index
                && task.source_start == 0
                && task.source_count == 2
        }));
    }

    #[test]
    fn resumed_frequency_adapter_replays_prefix_without_double_commit() {
        let schedule = schedule();
        let mut checkpoint = FemRunCheckpoint::new(&schedule, 1_000).unwrap();
        checkpoint.start(&schedule).unwrap();
        checkpoint
            .commit_next_task(&schedule, 0, schedule.lanes[0].tasks[0], 180)
            .unwrap();

        let mut cursor =
            FemFrequencyScheduleCursor::begin(&schedule, &mut checkpoint, 3, 2).unwrap();
        cursor.commit_frequency(0).unwrap();
        assert_eq!(cursor.checkpoint.next_task_index, 1);
        cursor.commit_frequency(1).unwrap();
        cursor.commit_frequency(2).unwrap();
        cursor.complete(None).unwrap();
        assert_eq!(
            checkpoint.status,
            super::super::run_state::FemRunStatus::Completed
        );
        assert_eq!(checkpoint.committed_task_count, 3);
    }

    #[test]
    fn frequency_adapter_commits_all_source_blocks_as_one_frequency() {
        let schedule = plan_solve_schedule(
            WorkloadShape {
                candidate_count: 1,
                frequency_count: 2,
                source_count: 3,
                rhs_block_size: 2,
            },
            ResourceBudget {
                lane_limit: 1,
                memory_budget_bytes: 1_000,
                shared_bytes: 100,
                per_lane_bytes: 100,
                per_frequency_bytes: 20,
                per_rhs_bytes: 30,
                per_output_bytes: 10,
            },
        )
        .unwrap();
        let tasks = frequency_tasks(&schedule, 2, 3).unwrap();
        assert_eq!(tasks.len(), 4);
        assert_eq!(tasks[0].source_start, 0);
        assert_eq!(tasks[0].source_count, 2);
        assert_eq!(tasks[1].source_start, 2);
        assert_eq!(tasks[1].source_count, 1);

        let mut malformed = schedule.clone();
        malformed.lanes[0].tasks[1].source_start = 1;
        assert!(frequency_tasks(&malformed, 2, 3).is_err());

        let mut checkpoint = FemRunCheckpoint::new(&schedule, 1_000).unwrap();
        let mut cursor =
            FemFrequencyScheduleCursor::begin(&schedule, &mut checkpoint, 2, 3).unwrap();
        cursor.commit_frequency(0).unwrap();
        assert_eq!(cursor.checkpoint.next_task_index, 2);
        cursor.commit_frequency(0).unwrap();
        assert_eq!(cursor.checkpoint.next_task_index, 2);
        cursor.commit_frequency(1).unwrap();
        cursor.complete(None).unwrap();
        assert_eq!(checkpoint.committed_task_count, 4);
        assert_eq!(checkpoint.status, FemRunStatus::Completed);
    }
}

#[cfg(test)]
mod lane_pool_tests {
    use super::super::fem_mesh_config::FemMeshConfig;
    use super::super::run_state::{FemRunCancellation, FemRunCheckpoint};
    use super::super::scheduler::{SolveLane, SolveSchedule, SolveWorkItem};
    use super::*;
    use sonium_xem::{Point3D, RectangularRoom, RoomGeometry, RoomSimulation, Source};

    #[test]
    fn lane_budget_splits_pool_without_oversubscription() {
        assert_eq!(lane_thread_budget(60, 4), 15);
        assert_eq!(lane_thread_budget(60, 1), 60);
        assert_eq!(lane_thread_budget(1, 4), 1);
        assert_eq!(lane_thread_budget(0, 4), 1);
        // A capped pool (e.g. `--max-concurrent 4`) splits instead of
        // re-dividing raw hardware parallelism (the old
        // `available_parallelism() / lanes` gave 32 here on a 128-CPU box).
        assert_eq!(lane_thread_budget(4, 2), 2);
        for pool_width in [1, 2, 7, 60] {
            for lanes in 1..=16 {
                let per_lane = lane_thread_budget(pool_width, lanes);
                assert!(per_lane >= 1, "pool={pool_width} lanes={lanes}");
                assert!(
                    per_lane <= pool_width.max(1),
                    "pool={pool_width} lanes={lanes}"
                );
                // In the feasible region (lanes <= width) the lanes jointly
                // stay within the admitted budget. Past it each lane keeps
                // one thread: oversubscription there is unavoidable sharing,
                // not a budget violation.
                if lanes <= pool_width.max(1) {
                    assert!(
                        per_lane * lanes <= pool_width.max(1),
                        "pool={pool_width} lanes={lanes}"
                    );
                }
            }
        }
    }

    fn tiny_candidate_simulation(lp: Point3D) -> RoomSimulation {
        let room = RectangularRoom::new(0.9, 0.8, 0.7);
        let source = Source::omnidirectional(Point3D::new(0.22, 0.31, 0.28), 1.0);
        RoomSimulation::with_frequencies(
            RoomGeometry::Rectangular(room),
            vec![source],
            vec![lp],
            80.0,
            80.0,
            1,
        )
    }

    fn two_lane_schedule() -> SolveSchedule {
        let lane = |lane_index: usize| SolveLane {
            lane_index,
            candidate_indices: vec![lane_index],
            tasks: vec![SolveWorkItem {
                candidate_index: lane_index,
                frequency_index: 0,
                source_start: 0,
                source_count: 1,
                estimated_bytes: 0,
            }],
            peak_bytes: 0,
        };
        SolveSchedule {
            lanes: vec![lane(0), lane(1)],
            task_count: 2,
            peak_concurrent_bytes: 0,
        }
    }

    /// Two full FEM solves through the concurrent candidate path: each lane
    /// pool runs nested assembly / GMRES / ILUT, which overflowed the default
    /// worker stack before lane pools carried the FEM-sized stack.
    #[test]
    fn concurrent_candidates_solve_inside_lane_pools() {
        let simulations = vec![
            tiny_candidate_simulation(Point3D::new(0.68, 0.53, 0.42)),
            tiny_candidate_simulation(Point3D::new(0.30, 0.55, 0.35)),
        ];
        let mesh_config = FemMeshConfig {
            fine_radius: 0.2,
            modal_damping_ratio: 0.02,
            ..FemMeshConfig::default()
        };
        let schedule = two_lane_schedule();
        assert_eq!(schedule.lanes.len(), 2);
        let mut checkpoint =
            FemRunCheckpoint::new(&schedule, 1_000_000_000).expect("two-lane checkpoint builds");
        let cancellation = FemRunCancellation::new();
        let mut outputs = vec![None, None];
        let solved = run_fem_candidates_concurrent_with_commit(
            &simulations,
            &mesh_config,
            &schedule,
            &mut checkpoint,
            &cancellation,
            &mut outputs,
            |_checkpoint, _task| Ok(()),
        )
        .expect("concurrent tiny-room candidates should solve");
        assert_eq!(solved.len(), 2);
        for output in &solved {
            assert_eq!(output.frequencies.len(), 1);
            let pressure = output.pressures[0][0][0];
            assert!(pressure.re.is_finite() && pressure.im.is_finite());
            assert!(pressure.norm() > 0.0);
        }
    }
}

/// Run FEM simulation for each source independently.
///
/// For every source, sweeps all frequencies and computes the complex pressure
/// at each listening position.  Returns `[source_idx][lp_idx][freq_idx]`.
pub fn run_fem(simulation: &RoomSimulation) -> Result<SimulationOutput> {
    run_fem_with_mesh(simulation, &FemMeshConfig::default())
}

pub fn run_fem_with_mesh(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
) -> Result<SimulationOutput> {
    Ok(run_fem_with_mesh_report(simulation, mesh_config)?.0)
}

/// Run a full physical-domain CPU FEM solve and retain its complex nodal
/// pressure field for spatial export.
///
/// This deliberately bypasses symmetry reduction: a retained field must have
/// physical-room coordinates and cannot be mistaken for a half-domain field.
pub fn run_fem_with_mesh_field_report(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
) -> Result<(SimulationOutput, FemNodalField, FemRunDiagnostics)> {
    validate_mesh_config(mesh_config)?;
    validate_geometry(simulation)?;
    validate_source_signal_ownership(simulation, mesh_config)?;
    let (output, field, diagnostics) =
        run_fem_full_report_with_field(simulation, mesh_config, true, None)?;
    diagnostics
        .require_converged()
        .map_err(anyhow::Error::msg)?;
    Ok((
        output,
        field.expect("field capture requested for full-domain FEM solve"),
        diagnostics,
    ))
}

/// Run a full-domain CPU FEM solve with cooperative cancellation.
///
/// The token is polled at frequency boundaries and inside the checked Krylov
/// solve boundaries, so cancellation never publishes a partial response. A
/// pre-cancelled token is rejected before mesh construction.
pub fn run_fem_with_mesh_cancellation(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
    cancellation: &FemRunCancellation,
) -> Result<SimulationOutput> {
    validate_mesh_config(mesh_config)?;
    validate_geometry(simulation)?;
    validate_source_signal_ownership(simulation, mesh_config)?;
    ensure_not_cancelled(cancellation)?;
    let (output, _field, diagnostics) =
        run_fem_full_report_with_field(simulation, mesh_config, false, Some(cancellation))?;
    diagnostics
        .require_converged()
        .map_err(anyhow::Error::msg)?;
    Ok(output)
}

/// Run a full-domain CPU FEM solve against a caller-owned schedule checkpoint.
///
/// The production frequency loop consumes a single-candidate schedule whose
/// tasks each cover one complete frequency/source batch. A resumed run replays
/// the committed frequency prefix to rebuild warm-start and recycling state,
/// then commits only the persisted cursor onward. The checkpoint therefore
/// restores deterministic progress without serializing transient solver data.
pub fn run_fem_with_mesh_checkpoint_cancellation(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
    schedule: &SolveSchedule,
    checkpoint: &mut FemRunCheckpoint,
    cancellation: &FemRunCancellation,
) -> Result<SimulationOutput> {
    run_fem_with_mesh_checkpoint_cancellation_with_commit(
        simulation,
        mesh_config,
        schedule,
        checkpoint,
        cancellation,
        |_checkpoint, _frequency_index| Ok(()),
    )
}

/// Run a checkpointed FEM solve and notify the caller after each committed
/// frequency. The callback executes before the next frequency begins, so a
/// caller can persist the durable cursor or request cooperative cancellation
/// without interrupting an in-flight sparse solve.
pub fn run_fem_with_mesh_checkpoint_cancellation_with_commit<F>(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
    schedule: &SolveSchedule,
    checkpoint: &mut FemRunCheckpoint,
    cancellation: &FemRunCancellation,
    mut on_commit: F,
) -> Result<SimulationOutput>
where
    F: FnMut(&mut FemRunCheckpoint, usize) -> Result<()>,
{
    validate_mesh_config(mesh_config)?;
    validate_geometry(simulation)?;
    validate_source_signal_ownership(simulation, mesh_config)?;
    ensure_not_cancelled(cancellation)?;
    let (output, _field, diagnostics) = run_fem_full_report_with_field_state(
        simulation,
        mesh_config,
        false,
        Some(cancellation),
        Some((schedule, checkpoint)),
        Some(&mut on_commit),
    )?;
    diagnostics
        .require_converged()
        .map_err(anyhow::Error::msg)?;
    Ok(output)
}

/// Run independent candidate rooms concurrently through the production CPU
/// FEM path, using one schedule task per candidate.
///
/// `outputs` is caller-owned continuation state. Pending runs require empty
/// slots; a resumed run must retain outputs for every committed task and leave
/// later slots empty. This makes checkpoint resume lossless for completed
/// candidates without hiding output ownership inside the scheduler.
pub fn run_fem_candidates_concurrent(
    simulations: &[RoomSimulation],
    mesh_config: &FemMeshConfig,
    schedule: &SolveSchedule,
    checkpoint: &mut FemRunCheckpoint,
    cancellation: &FemRunCancellation,
    outputs: &mut [Option<SimulationOutput>],
) -> Result<Vec<SimulationOutput>> {
    run_fem_candidates_concurrent_with_commit(
        simulations,
        mesh_config,
        schedule,
        checkpoint,
        cancellation,
        outputs,
        |_checkpoint, _task| Ok(()),
    )
}

/// Run candidate rooms concurrently and notify the caller after each
/// candidate checkpoint commit.
///
/// The callback runs after the corresponding output slot has been populated
/// and the checkpoint cursor has advanced. It can persist the checkpoint or
/// request cooperative cancellation for a deterministic interruption test;
/// the caller retains ownership of the output slots.
/// Build the admitted schedule used by the production candidate runner.
///
/// Candidate dispatch treats each independent room as one continuation task:
/// the task owns the complete frequency sweep and all source RHS work for
/// that candidate. The schedule still carries lane affinity and the resource
/// admission estimate used by the concurrent executor.
pub fn plan_fem_candidate_schedule(
    candidate_count: usize,
    budget: ResourceBudget,
) -> Result<SolveSchedule> {
    plan_solve_schedule(
        WorkloadShape {
            candidate_count,
            frequency_count: 1,
            source_count: 1,
            rhs_block_size: 1,
        },
        budget,
    )
    .map_err(anyhow::Error::msg)
}

/// Run independent candidate rooms using an internally planned schedule.
///
/// This convenience entry point is for a fresh run. Callers that need
/// durable resume or custom commit persistence should use
/// [`run_fem_candidates_concurrent`] with a checkpoint created from
/// [`plan_fem_candidate_schedule`].
pub fn run_fem_candidates_concurrent_with_budget(
    simulations: &[RoomSimulation],
    mesh_config: &FemMeshConfig,
    budget: ResourceBudget,
    cancellation: &FemRunCancellation,
) -> Result<Vec<SimulationOutput>> {
    anyhow::ensure!(
        !simulations.is_empty(),
        "candidate workload requires at least one simulation"
    );
    let schedule = plan_fem_candidate_schedule(simulations.len(), budget)?;
    let mut checkpoint =
        FemRunCheckpoint::new(&schedule, budget.memory_budget_bytes).map_err(anyhow::Error::msg)?;
    let mut outputs = vec![None; simulations.len()];
    run_fem_candidates_concurrent(
        simulations,
        mesh_config,
        &schedule,
        &mut checkpoint,
        cancellation,
        &mut outputs,
    )
}

/// Split a process-wide thread budget across candidate lanes.
///
/// `pool_width` is the admitted parallelism: the global Rayon pool width,
/// which already encodes `--max-concurrent` / `RAYON_NUM_THREADS`. Each lane
/// gets an equal share of at least one thread, so concurrent lanes divide —
/// rather than multiply — the admitted budget. Deriving the share from raw
/// `available_parallelism()` instead oversubscribes the pool whenever the
/// user capped threads below the hardware count.
fn lane_thread_budget(pool_width: usize, lane_count: usize) -> usize {
    (pool_width.max(1) / lane_count.max(1)).max(1)
}

pub fn run_fem_candidates_concurrent_with_commit<F>(
    simulations: &[RoomSimulation],
    mesh_config: &FemMeshConfig,
    schedule: &SolveSchedule,
    checkpoint: &mut FemRunCheckpoint,
    cancellation: &FemRunCancellation,
    outputs: &mut [Option<SimulationOutput>],
    on_commit: F,
) -> Result<Vec<SimulationOutput>>
where
    F: FnMut(&mut FemRunCheckpoint, SolveWorkItem) -> Result<(), String>,
{
    anyhow::ensure!(
        !simulations.is_empty(),
        "candidate FEM run requires candidates"
    );
    anyhow::ensure!(
        outputs.len() == simulations.len(),
        "candidate output slots must match candidate count"
    );
    let tasks = candidate_tasks(schedule, simulations.len())?;
    checkpoint
        .validate_for(schedule)
        .map_err(anyhow::Error::msg)?;

    match checkpoint.status {
        FemRunStatus::Pending => {
            anyhow::ensure!(
                outputs.iter().all(Option::is_none),
                "pending candidate run cannot contain output slots"
            );
        }
        FemRunStatus::Running | FemRunStatus::Cancelled => {
            for (task_index, task) in tasks.iter().enumerate() {
                let has_output = outputs[task.candidate_index].is_some();
                anyhow::ensure!(
                    has_output == (task_index < checkpoint.next_task_index),
                    "candidate output slots do not match the checkpoint cursor"
                );
            }
        }
        FemRunStatus::Completed => {
            anyhow::ensure!(
                outputs.iter().all(Option::is_some),
                "completed candidate run is missing an output"
            );
            return outputs
                .iter()
                .cloned()
                .map(|output| output.ok_or_else(|| anyhow::anyhow!("missing candidate output")))
                .collect();
        }
    }

    anyhow::ensure!(
        !schedule.lanes.is_empty(),
        "candidate schedule requires lanes"
    );
    // Lane pools split the admitted process-wide budget (the global pool
    // width already reflects `--max-concurrent` / RAYON_NUM_THREADS) instead
    // of re-dividing raw hardware parallelism, which oversubscribed the pool
    // whenever the user capped threads below the machine count. They also
    // carry the FEM-sized worker stack: full solves running inside a lane
    // overflow the default ~2 MiB worker stack.
    let pool_width = rayon::current_num_threads().max(1);
    let threads_per_lane = lane_thread_budget(pool_width, schedule.lanes.len());
    let lane_pools = Arc::new(
        (0..schedule.lanes.len())
            .map(|lane| {
                rayon::ThreadPoolBuilder::new()
                    .num_threads(threads_per_lane)
                    .stack_size(crate::runtime::FEM_WORKER_STACK_BYTES)
                    .thread_name(move |index| format!("fem-lane-{lane}-{index}"))
                    .build()
                    .map_err(|error| anyhow::anyhow!("failed to build FEM lane pool: {error}"))
            })
            .collect::<Result<Vec<_>>>()?,
    );
    let candidate_simulations = simulations.to_vec();
    let output_slots = Arc::new(Mutex::new(outputs.to_vec()));
    let worker_output_slots = output_slots.clone();
    let worker_cancellation = cancellation.clone();
    let worker_lane_pools = lane_pools.clone();
    let execution = execute_scheduled_fem_run_concurrent_with_commit(
        schedule,
        checkpoint,
        cancellation,
        move |task| {
            let lane_index = task.candidate_index % worker_lane_pools.len();
            let output = worker_lane_pools[lane_index]
                .install(|| {
                    run_fem_with_mesh_cancellation(
                        &candidate_simulations[task.candidate_index],
                        mesh_config,
                        &worker_cancellation,
                    )
                })
                .map_err(|error| error.to_string())?;
            let mut slots = worker_output_slots
                .lock()
                .map_err(|_| "candidate output slot mutex poisoned".to_string())?;
            slots[task.candidate_index] = Some(output);
            Ok(task.estimated_bytes)
        },
        on_commit,
    );

    let mut restored_outputs = Arc::try_unwrap(output_slots)
        .map_err(|_| anyhow::anyhow!("candidate output slots still have active workers"))?
        .into_inner()
        .map_err(|_| anyhow::anyhow!("candidate output slot mutex poisoned"))?;
    if execution.is_err() {
        // Workers publish outputs as solves finish, ahead of the
        // in-order commit. On interruption only committed tasks may
        // retain their output: leaving an uncommitted slot populated
        // would contradict the checkpoint cursor and make the run
        // unresumable, so discard every output at or past the cursor.
        for (task_index, task) in tasks.iter().enumerate() {
            if task_index >= checkpoint.next_task_index {
                restored_outputs[task.candidate_index] = None;
            }
        }
    }
    outputs.clone_from_slice(&restored_outputs);
    execution.map_err(anyhow::Error::msg)?;

    restored_outputs
        .into_iter()
        .enumerate()
        .map(|(candidate_index, output)| {
            output.ok_or_else(|| anyhow::anyhow!("candidate {candidate_index} produced no output"))
        })
        .collect()
}

fn candidate_tasks(schedule: &SolveSchedule, candidate_count: usize) -> Result<Vec<SolveWorkItem>> {
    anyhow::ensure!(
        schedule.task_count == candidate_count,
        "candidate schedule must contain one task per candidate"
    );
    anyhow::ensure!(
        !schedule.lanes.is_empty(),
        "candidate schedule requires lanes"
    );
    let mut seen = vec![false; candidate_count];
    let mut tasks = Vec::with_capacity(candidate_count);
    for (lane_index, lane) in schedule.lanes.iter().enumerate() {
        anyhow::ensure!(
            lane.lane_index == lane_index,
            "candidate schedule lane indices must be contiguous"
        );
        for task in &lane.tasks {
            anyhow::ensure!(
                task.candidate_index < candidate_count
                    && task.candidate_index % schedule.lanes.len() == lane_index
                    && task.frequency_index == 0
                    && task.source_start == 0
                    && task.source_count == 1,
                "candidate schedule task must be a single frequency/source task"
            );
            anyhow::ensure!(
                !seen[task.candidate_index],
                "candidate schedule contains a duplicate candidate"
            );
            seen[task.candidate_index] = true;
            tasks.push(*task);
        }
    }
    anyhow::ensure!(
        seen.into_iter().all(|assigned| assigned),
        "candidate schedule omits a candidate"
    );
    Ok(tasks)
}

/// Full-domain CPU FEM cancellation variant retaining the solved nodal field.
pub fn run_fem_with_mesh_field_report_cancellation(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
    cancellation: &FemRunCancellation,
) -> Result<(SimulationOutput, FemNodalField, FemRunDiagnostics)> {
    validate_mesh_config(mesh_config)?;
    validate_geometry(simulation)?;
    validate_source_signal_ownership(simulation, mesh_config)?;
    ensure_not_cancelled(cancellation)?;
    let (output, field, diagnostics) =
        run_fem_full_report_with_field(simulation, mesh_config, true, Some(cancellation))?;
    diagnostics
        .require_converged()
        .map_err(anyhow::Error::msg)?;
    Ok((
        output,
        field.expect("field capture requested full-domain FEM solve"),
        diagnostics,
    ))
}

pub fn run_fem_with_mesh_report(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
) -> Result<(SimulationOutput, FemRunDiagnostics)> {
    validate_mesh_config(mesh_config)?;
    validate_geometry(simulation)?;
    validate_source_signal_ownership(simulation, mesh_config)?;
    let symmetry = detect_symmetry(simulation);
    let result = if !symmetry.planes.is_empty() {
        log::info!(
            "FEM: detected symmetry planes: {:?} ({}x reduction)",
            symmetry.planes,
            symmetry.reduction_factor(),
        );
        run_fem_symmetric_report(simulation, &symmetry, mesh_config)
    } else {
        run_fem_full_report(simulation, mesh_config)
    }?;
    result.1.require_converged().map_err(anyhow::Error::msg)?;
    Ok(result)
}

/// Run the CPU FEM solver on the full physical room, bypassing automatic
/// symmetry reduction. This is useful for external reference-solver comparisons
/// where both solvers must use the same full-domain mesh.
pub fn run_fem_full_domain_with_mesh_report(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
) -> Result<(SimulationOutput, FemRunDiagnostics)> {
    validate_mesh_config(mesh_config)?;
    validate_geometry(simulation)?;
    validate_source_signal_ownership(simulation, mesh_config)?;
    let result = run_fem_full_report(simulation, mesh_config)?;
    result.1.require_converged().map_err(anyhow::Error::msg)?;
    Ok(result)
}

pub(super) fn run_fem_full_report(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
) -> Result<(SimulationOutput, FemRunDiagnostics)> {
    let (output, _field, diagnostics) =
        run_fem_full_report_with_field(simulation, mesh_config, false, None)?;
    Ok((output, diagnostics))
}

pub(super) fn run_fem_full_report_with_field(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
    capture_field: bool,
    cancellation: Option<&FemRunCancellation>,
) -> Result<(SimulationOutput, Option<FemNodalField>, FemRunDiagnostics)> {
    run_fem_full_report_with_field_state(
        simulation,
        mesh_config,
        capture_field,
        cancellation,
        None,
        None,
    )
}

/// Full FEM report outcome: `(output, captured_field, diagnostics)`.
type FemFullReportOutcome = (SimulationOutput, Option<FemNodalField>, FemRunDiagnostics);

/// Optional per-frequency checkpoint commit callback.
type OnFrequencyCommit<'a> = Option<&'a mut dyn FnMut(&mut FemRunCheckpoint, usize) -> Result<()>>;

fn run_fem_full_report_with_field_state(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
    capture_field: bool,
    cancellation: Option<&FemRunCancellation>,
    run_state: Option<(&SolveSchedule, &mut FemRunCheckpoint)>,
    mut on_frequency_commit: OnFrequencyCommit<'_>,
) -> Result<FemFullReportOutcome> {
    anyhow::ensure!(
        !simulation.frequencies.is_empty(),
        "FEM solve requires at least one frequency"
    );
    if let Some(cancellation) = cancellation {
        ensure_not_cancelled(cancellation)?;
    }
    let mut schedule_cursor = if let Some((schedule, checkpoint)) = run_state {
        Some(FemFrequencyScheduleCursor::begin(
            schedule,
            checkpoint,
            simulation.frequencies.len(),
            simulation.sources.len(),
        )?)
    } else {
        None
    };
    let max_freq = simulation
        .frequencies
        .iter()
        .cloned()
        .fold(f64::NEG_INFINITY, f64::max);
    let min_wavelength = simulation.speed_of_sound / max_freq;
    let elements_per_meter = (mesh_config.elements_per_wavelength / min_wavelength).ceil() as usize;

    log::info!(
        "FEM: building mesh for max_freq={:.0} Hz, grading {:.1}x",
        max_freq,
        mesh_config.grading_factor,
    );
    let mesh_start = Instant::now();
    let mesh = cached_room_mesh(
        simulation,
        elements_per_meter,
        &SymmetryConfig::none(),
        mesh_config,
    );
    log::info!(
        "FEM mesh: {} nodes, {} elements (fine spacing {} elem/m for {:.0} Hz max, grading {:.1}x, radius {:.2} m) built in {}",
        mesh.num_nodes(),
        mesh.num_elements(),
        elements_per_meter,
        max_freq,
        mesh_config.grading_factor,
        mesh_config.fine_radius,
        fmt_duration(mesh_start.elapsed()),
    );

    // Image-source mirror walls = the mesh AABB itself in the full solve
    // (every face of the mesh is a physical wall here).
    let image_walls_aabb = mesh_aabb(&mesh);

    // Assemble frequency-independent matrices once
    log::info!("FEM: assembling frequency-independent matrices");
    let assembly_start = Instant::now();
    let stiffness = assemble_stiffness(&mesh, PolynomialDegree::P1);
    let mass = assemble_mass(&mesh, PolynomialDegree::P1);

    let markers = [
        MARKER_FLOOR,
        MARKER_CEILING,
        MARKER_FRONT,
        MARKER_BACK,
        MARKER_LEFT,
        MARKER_RIGHT,
    ];
    let mut boundary_matrices = Vec::new();
    for &marker in &markers {
        let b_mass = assemble_boundary_mass(&mesh, PolynomialDegree::P1, marker);
        if b_mass.nnz() > 0 {
            boundary_matrices.push((marker as usize, b_mass));
        }
    }

    let preconditioner = mesh_config.preconditioner;
    let geometric_schwarz =
        append_geometric_schwarz_boundary_matrices(&mesh, preconditioner, &mut boundary_matrices);

    let assembler = HelmholtzAssembler::from_matrices(&stiffness, &mass, &boundary_matrices);
    if let Some(transmission) = &geometric_schwarz {
        log::info!(
            "FEM: added geometry-exact {} interface terms on {} faces across {} subdomains",
            preconditioner,
            transmission.face_count,
            transmission.partitions.len(),
        );
    }
    log::info!(
        "FEM: assembled K nnz={}, M nnz={}, {} boundary matrices in {}",
        stiffness.nnz(),
        mass.nnz(),
        boundary_matrices.len(),
        fmt_duration(assembly_start.elapsed()),
    );

    // Resolve frequency-independent surface descriptions once.
    let resolved_boundaries = resolve_boundaries(simulation)?;

    // Pre-locate elements containing listening positions.
    // Sequential outer loop: `find_containing_element_parallel` already
    // parallelises across mesh elements (typically 100k+), so wrapping
    // the small LP iteration (typically 1–10) in another par_iter would
    // only nest rayon pools and oversubscribe.
    let locate_start = Instant::now();
    let lp_elements: Vec<Option<usize>> = simulation
        .listening_positions
        .iter()
        .map(|lp| find_containing_element_parallel(&mesh, *lp))
        .collect();
    let (lp_interpolations, listener_fallbacks) =
        build_listener_interpolations(&mesh, &simulation.listening_positions, &lp_elements);
    if listener_fallbacks > 0 {
        log::warn!(
            "FEM: {listener_fallbacks} of {} listening positions fell back to nearest-node interpolation",
            lp_elements.len()
        );
    }
    log::info!(
        "FEM: located {} listening positions in {}",
        lp_elements.len(),
        fmt_duration(locate_start.elapsed()),
    );

    // GMRES with a shifted-Laplacian preconditioner. The matrix and
    // preconditioner are frequency-dependent but source-independent, so build
    // them once per frequency and reuse them for every source RHS.
    let gmres_config = gmres_config(mesh_config);
    let ilut_config = IlutConfig {
        // 1e-5 (vs the older 1e-4) keeps more of the Helmholtz operator's
        // off-diagonal coupling. For Complex64 indefinite systems the dropped
        // entries accumulate and visibly slow GMRES convergence; this is
        // small enough not to noticeably grow fill but tight enough to keep
        // iteration counts stable across the frequency sweep.
        drop_tolerance: 1e-5,
        fill_factor: 20,
        pivot_tolerance: 1e-10,
        pivoting: true,
    };
    let recycle_subspace_size = effective_recycle_subspace_size(mesh_config);
    let gmres_mode = if preconditioner == FemPreconditionerKind::Amg {
        "FGMRES".to_string()
    } else {
        gmres_mode_label(recycle_subspace_size, mesh_config.recycler)
    };

    let n_sources = simulation.sources.len();
    let n_lps = simulation.listening_positions.len();
    let n_freqs = simulation.frequencies.len();

    let mut pressures: Vec<Vec<Vec<Complex64>>> =
        vec![vec![vec![Complex64::new(0.0, 0.0); n_freqs]; n_lps]; n_sources];
    let mut nodal_pressures = capture_field
        .then(|| vec![vec![vec![Complex64::new(0.0, 0.0); mesh.num_nodes()]; n_freqs]; n_sources]);
    let mut diagnostics = FemRunDiagnostics::new("cpu", mesh_config);
    diagnostics.listener_interpolation_fallbacks = listener_fallbacks;

    let vtu_dir = std::env::var("SONIUM_ROOM_VTU_DIR")
        .ok()
        .map(std::path::PathBuf::from);
    if let Some(ref dir) = vtu_dir {
        std::fs::create_dir_all(dir).ok();
        let _ =
            sonium_xem::io::vtu::VtuWriter::new(mesh.as_ref()).write(dir.join("fem_room_mesh.vtu"));
    }

    let safe_names: Vec<String> = simulation
        .sources
        .iter()
        .map(|source| source.name.replace([' ', '/', '\\'], "_"))
        .collect();
    let mut pvds: Vec<_> = safe_names
        .iter()
        .map(|safe_name| {
            vtu_dir.as_ref().map(|d| {
                sonium_xem::io::PvdCollection::new(d.join(format!("fem_source_{safe_name}.pvd")))
            })
        })
        .collect();
    let mut prev_solutions: Vec<Option<Vec<Complex64>>> = vec![None; n_sources];
    let mut recycled_subspaces =
        build_recycle_subspaces(recycle_subspace_size, mesh_config.recycler, n_sources);
    let rebuild_every = mesh_config.rebuild_precond_every.max(1);
    let recycle_reset_every = mesh_config.recycle_reset_every;
    let mut cached_precond: Option<FemPreconditioner> = None;
    let mut preconditioner_age = 0usize;
    let mut force_preconditioner_rebuild = false;
    let mut recent_iterations = Vec::new();
    let mut csr = assembler.empty_matrix();
    let mut p_matrix = assembler.empty_matrix();
    let rhs_basis_start = Instant::now();
    let rhs_bases: Vec<SourceRhsBasis> = simulation
        .sources
        .iter()
        .map(|source| {
            build_source_rhs_basis_for_model(
                &mesh,
                source,
                image_walls_aabb,
                mesh_config.source_model,
            )
        })
        .collect::<Result<Vec<_>>>()?;
    log::info!(
        "FEM: precomputed {} source RHS bases in {}",
        rhs_bases.len(),
        fmt_duration(rhs_basis_start.elapsed()),
    );
    for source in &simulation.sources {
        // A BEM-exported complex grid already contains the speaker crossover
        // (magnitude AND phase) and multi-driver interference; multiplying by
        // a room-side crossover filter would double-count it. Warn only —
        // chained filtering (e.g. an extra room-EQ stage) can be legitimate.
        if matches!(source.directivity, Directivity::ComplexGrid(_))
            && !matches!(source.crossover, CrossoverFilter::FullRange)
        {
            log::warn!(
                "source '{}': complex directivity grid combined with a non-fullrange crossover filter; the grid already contains the speaker crossover — set the source crossover to fullrange unless chaining is intentional",
                source.name
            );
        }
    }
    let mut rhs_buffers = vec![vec![Complex64::new(0.0, 0.0); mesh.num_nodes()]; n_sources];

    log::info!(
        "FEM: solving {} sources x {} frequencies with shifted-Laplacian {} preconditioner, shift {}, and {} (rebuild every {} freq{})",
        n_sources,
        n_freqs,
        preconditioner,
        mesh_config.shifted_laplacian_shift,
        gmres_mode,
        rebuild_every,
        if rebuild_every == 1 { "" } else { "s" },
    );

    for (freq_idx, &freq) in simulation.frequencies.iter().enumerate() {
        if let Some(cursor) = schedule_cursor.as_mut()
            && let Some(cancellation) = cancellation
        {
            cursor.poll_cancellation(cancellation)?;
        }
        if let Some(cancellation) = cancellation {
            ensure_not_cancelled(cancellation)?;
        }
        let freq_start = Instant::now();
        let k = simulation.wavenumber(freq);
        // Complex wavenumber including atmospheric absorption AND a minimum
        // modal damping floor — gives finite modal Q from volumetric losses
        // on top of boundary losses, and prevents GMRES stalls at real-axis
        // modal poles.
        let k_complex = complex_wavenumber(k, freq, mesh_config.modal_damping_ratio);

        if recycle_reset_every > 0
            && freq_idx > 0
            && freq_idx.is_multiple_of(recycle_reset_every)
            && recycled_subspaces.is_some()
        {
            log::debug!(
                "FEM: resetting recycled subspaces at frequency {}/{} ({:.1} Hz)",
                freq_idx + 1,
                n_freqs,
                freq,
            );
            recycled_subspaces =
                build_recycle_subspaces(recycle_subspace_size, mesh_config.recycler, n_sources);
        }

        if should_log_frequency(freq_idx, n_freqs) {
            log::info!(
                "FEM: frequency {}/{} ({:.1} Hz) started",
                freq_idx + 1,
                n_freqs,
                freq,
            );
        } else {
            log::debug!(
                "FEM: frequency {}/{} ({:.1} Hz) started",
                freq_idx + 1,
                n_freqs,
                freq,
            );
        }

        let matrix_start = Instant::now();
        let boundary_coeffs =
            compute_boundary_coefficients(simulation, &resolved_boundaries, freq)?;
        let must_rebuild = cached_precond.is_none()
            || freq_idx % rebuild_every == 0
            || force_preconditioner_rebuild;
        let mut rebuild_reason = if cached_precond.is_none() {
            "initial"
        } else if force_preconditioner_rebuild {
            "iteration-spike"
        } else if freq_idx % rebuild_every == 0 {
            "scheduled"
        } else {
            "cached"
        }
        .to_string();
        let mut matrix_time;
        let mut precond_time;
        if must_rebuild {
            let p_shift = mesh_config.shifted_laplacian_shift.value(k);
            let p_boundary_coeffs = geometric_schwarz_coefficients(preconditioner, k);
            assembler.assemble_helmholtz_and_shift_with_preconditioner_boundaries_into(
                k_complex,
                &boundary_coeffs,
                p_shift,
                &p_boundary_coeffs,
                &mut csr,
                &mut p_matrix,
            );
            matrix_time = matrix_start.elapsed();
            log::debug!(
                "FEM: building {} preconditioner for {:.1} Hz",
                preconditioner,
                freq
            );
            let precond_start = Instant::now();
            cached_precond = Some(build_preconditioner(
                &p_matrix,
                preconditioner,
                &ilut_config,
                k,
                geometric_schwarz
                    .as_ref()
                    .map(|transmission| transmission.partitions.as_slice()),
            ));
            precond_time = precond_start.elapsed();
            preconditioner_age = 0;
        } else {
            assembler.assemble_into(k_complex, &boundary_coeffs, &mut csr);
            matrix_time = matrix_start.elapsed();
            precond_time = Duration::ZERO;
            preconditioner_age += 1;
        }
        let precond = cached_precond
            .as_ref()
            .expect("rebuild path always populates cached_precond");

        // Block multi-source solve (config-gated): assemble every source RHS,
        // stack them into one n×k block, and run a single block Krylov solve
        // with the stacked previous solutions as warm start. Sources whose
        // per-RHS true residual fails the gate fall through to the same
        // serial retry ladder as the per-source path below (recycler cleared,
        // strong ILUT, BiCGSTAB).
        let stats: Vec<SourceStats> = if mesh_config.block_source_solve && n_sources >= 2 {
            let rhs_start = Instant::now();
            // Same fan-out discipline as the per-source solve loop below:
            // inner assembly/solve parallelism already saturates the pool,
            // so below half the pool width this stays serial.
            let pool_threads = rayon::current_num_threads().max(1);
            let serial_rhs = std::env::var("SONIUM_SERIAL")
                .map(|value| matches!(value.to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
                .unwrap_or(false)
                || std::env::var("SONIUM_SIMROOM_PAR_MIN_SOURCES")
                    .ok()
                    .and_then(|value| value.parse::<usize>().ok())
                    .map(|min| n_sources < min)
                    .unwrap_or_else(|| n_sources < (pool_threads / 2).max(2));
            if serial_rhs {
                rhs_buffers
                    .iter_mut()
                    .enumerate()
                    .for_each(|(src_idx, rhs)| {
                        assemble_rhs_from_basis_into(
                            &rhs_bases[src_idx],
                            &simulation.sources[src_idx],
                            freq,
                            rhs,
                        );
                    });
            } else {
                rhs_buffers
                    .par_iter_mut()
                    .enumerate()
                    .for_each(|(src_idx, rhs)| {
                        assemble_rhs_from_basis_into(
                            &rhs_bases[src_idx],
                            &simulation.sources[src_idx],
                            freq,
                            rhs,
                        );
                    });
            }
            let rhs_time_total = rhs_start.elapsed();

            let n_dofs = mesh.num_nodes();
            let mut b_block = DenseMatrix::from_elem(n_dofs, n_sources, Complex64::new(0.0, 0.0));
            for (j, rhs) in rhs_buffers.iter().enumerate() {
                b_block.set_column(j, rhs);
            }
            // Warm-start X₀ from the stacked previous-frequency solutions
            // (zero columns where no previous solution exists yet). The
            // block path deliberately uses warm-start instead of the
            // per-source GCRO-DR recycled subspaces.
            let x0 = if prev_solutions.iter().any(Option::is_some) {
                let mut x0 = DenseMatrix::from_elem(n_dofs, n_sources, Complex64::new(0.0, 0.0));
                for (j, prev) in prev_solutions.iter().enumerate() {
                    if let Some(prev) = prev {
                        x0.set_column(j, prev);
                    }
                }
                Some(x0)
            } else {
                None
            };

            let source_blocks = schedule_cursor
                .as_ref()
                .map(|cursor| cursor.source_blocks_for_frequency(freq_idx))
                .transpose()?
                .unwrap_or_else(|| vec![(0, n_sources)]);
            let solve_start = Instant::now();
            let block = if let Some(cancellation) = cancellation {
                match solve_frequency_block_partitioned_with_abort(
                    &csr,
                    precond,
                    &b_block,
                    x0.as_ref(),
                    &gmres_config,
                    &source_blocks,
                    || cancellation.is_cancelled(),
                ) {
                    Ok(block) => block,
                    Err(error) => {
                        if cancellation.is_cancelled() {
                            cancellation.cancel(error.clone());
                            if let Some(cursor) = schedule_cursor.as_mut() {
                                cursor.poll_cancellation(cancellation)?;
                            }
                            return Err(anyhow::Error::msg(error));
                        }
                        solve_frequency_block_partitioned(
                            &csr,
                            precond,
                            &b_block,
                            x0.as_ref(),
                            &gmres_config,
                            &source_blocks,
                        )
                        .map_err(anyhow::Error::msg)?
                    }
                }
            } else {
                solve_frequency_block_partitioned(
                    &csr,
                    precond,
                    &b_block,
                    x0.as_ref(),
                    &gmres_config,
                    &source_blocks,
                )
                .map_err(anyhow::Error::msg)?
            };
            let solve_time_total = solve_start.elapsed();
            // Per-source shares of the block timings so the aggregated
            // frequency stats stay comparable to the per-source path (which
            // sums per-source durations).
            let rhs_share = rhs_time_total / n_sources as u32;
            let solve_share = solve_time_total / n_sources as u32;

            (0..n_sources)
                .map(|src_idx| {
                    let source = &simulation.sources[src_idx];
                    let true_res = block.true_residuals[src_idx];
                    let solution = block.x.column_to_vec(src_idx);
                    if !(true_res.is_finite() && true_res <= gmres_config.tolerance) {
                        log::warn!(
                            "FEM block solve failed for source {} freq {:.1} Hz: iters={} true_res={:.2e} (falling back to per-source retry ladder)",
                            source.name,
                            freq,
                            block.iterations,
                            true_res,
                        );
                        return SourceStats {
                            iterations: block.iterations,
                            residual: true_res,
                            rhs_time: rhs_share,
                            solve_time: solve_share,
                            converged: false,
                            failed_solution: Some(solution),
                            accepted_solution: None,
                        };
                    }

                    let mut lp_pressures =
                        vec![Complex64::new(0.0, 0.0); simulation.listening_positions.len()];
                    for (lp_idx, interp) in lp_interpolations.iter().enumerate() {
                        lp_pressures[lp_idx] = evaluate_listener_interpolation(&solution, interp);
                    }
                    store_listener_pressures(
                        &simulation.listening_positions,
                        &lp_pressures,
                        source,
                        freq,
                        &mut pressures[src_idx],
                        freq_idx,
                    );

                    if let (Some(dir), Some(p)) = (vtu_dir.as_ref(), pvds[src_idx].as_mut()) {
                        let mut w = sonium_xem::io::vtu::VtuWriter::new(mesh.as_ref());
                        w.add_point_scalar_complex("pressure", solution.as_slice());
                        let fname = format!("fem_{}_f{:06.1}Hz.vtu", safe_names[src_idx], freq);
                        let _ = w.write(dir.join(&fname));
                        p.push(freq, fname);
                    }

                    prev_solutions[src_idx] = Some(solution.clone());

                    SourceStats {
                        iterations: block.iterations,
                        residual: true_res,
                        rhs_time: rhs_share,
                        solve_time: solve_share,
                        converged: true,
                        failed_solution: None,
                        accepted_solution: Some(solution),
                    }
                })
                .collect()
        } else {
            // Sources are independent: A and the preconditioner are read-only,
            // and per-source state (pressures slice, prev_solution, recycled
            // subspace, PVD) lives in disjoint slots. Solve them in parallel
            // only when the source count justifies a second fan-out level:
            // inner assembly/GMRES/ILUT par_iters already saturate the pool,
            // so below half the pool width the loop runs serially and lets
            // nested parallelism use full cores. Override with
            // SONIUM_SIMROOM_PAR_MIN_SOURCES (absolute source count).
            let pool_threads = rayon::current_num_threads().max(1);
            let serial_override = std::env::var("SONIUM_SERIAL")
                .map(|value| matches!(value.to_ascii_lowercase().as_str(), "1" | "true" | "yes"))
                .unwrap_or(false);
            let min_parallel_sources = std::env::var("SONIUM_SIMROOM_PAR_MIN_SOURCES")
                .ok()
                .and_then(|value| value.parse::<usize>().ok())
                .unwrap_or_else(|| (pool_threads / 2).max(2));
            let parallel_sources = !serial_override && n_sources >= min_parallel_sources;
            let recycled_per_source: Vec<Option<&mut FemRecycleSubspace>> =
                match recycled_subspaces.as_mut() {
                    Some(v) => v.iter_mut().map(Some).collect(),
                    None => (0..n_sources).map(|_| None).collect(),
                };

            type SourceWork<'a> = (
                (
                    (
                        (
                            (&'a Source, &'a mut Vec<Vec<Complex64>>),
                            &'a mut Option<Vec<Complex64>>,
                        ),
                        &'a mut Option<sonium_xem::io::PvdCollection>,
                    ),
                    Option<&'a mut FemRecycleSubspace>,
                ),
                &'a mut Vec<Complex64>,
            );
            let solve_source = |(src_idx, work): (usize, SourceWork<'_>)| {
                let (((((source, src_pressures), prev_sol), pvd_slot), recycled_subspace), rhs) =
                    work;
                log::debug!(
                    "FEM: solving source {} of {} ({}) at {:.1} Hz",
                    src_idx + 1,
                    n_sources,
                    source.name,
                    freq,
                );

                let rhs_start = Instant::now();
                assemble_rhs_from_basis_into(&rhs_bases[src_idx], source, freq, rhs);
                let rhs_time = rhs_start.elapsed();

                let solve_start = Instant::now();
                let result =
                    if let Some(cancellation) = cancellation {
                        match solve_frequency_system_with_abort(
                            &csr,
                            precond,
                            rhs,
                            prev_sol.as_deref(),
                            &gmres_config,
                            || cancellation.is_cancelled(),
                        ) {
                            Ok(result) => result,
                            Err(error) if cancellation.is_cancelled() => {
                                cancellation.cancel(error.clone());
                                return SourceStats {
                                    iterations: 0,
                                    residual: f64::INFINITY,
                                    rhs_time,
                                    solve_time: solve_start.elapsed(),
                                    converged: false,
                                    failed_solution: Some(prev_sol.clone().unwrap_or_else(|| {
                                        vec![Complex64::new(0.0, 0.0); rhs.len()]
                                    })),
                                    accepted_solution: None,
                                };
                            }
                            Err(_error) => solve_frequency_system(
                                &csr,
                                precond,
                                rhs,
                                prev_sol.as_deref(),
                                recycled_subspace,
                                &gmres_config,
                            ),
                        }
                    } else {
                        solve_frequency_system(
                            &csr,
                            precond,
                            rhs,
                            prev_sol.as_deref(),
                            recycled_subspace,
                            &gmres_config,
                        )
                    };
                let solve_time = solve_start.elapsed();

                // On failure: log a warning but do NOT overwrite prev_sol
                // or src_pressures. The post-par_iter retry path needs the
                // last successful warm-start and the chance to fill
                // pressures with a real value (or bail if it can't).
                if !result.converged {
                    log::warn!(
                        "FEM solve failed for source {} freq {:.1} Hz on first pass: iters={} res={:.2e} (will retry with cleared recycler)",
                        source.name,
                        freq,
                        result.iterations,
                        result.residual,
                    );
                    return SourceStats {
                        iterations: result.iterations,
                        residual: result.residual,
                        rhs_time,
                        solve_time,
                        converged: false,
                        failed_solution: Some(result.x),
                        accepted_solution: None,
                    };
                }
                let solution = result.x;

                let mut lp_pressures =
                    vec![Complex64::new(0.0, 0.0); simulation.listening_positions.len()];
                for (lp_idx, interp) in lp_interpolations.iter().enumerate() {
                    lp_pressures[lp_idx] = evaluate_listener_interpolation(&solution, interp);
                }
                store_listener_pressures(
                    &simulation.listening_positions,
                    &lp_pressures,
                    source,
                    freq,
                    src_pressures,
                    freq_idx,
                );

                if let (Some(dir), Some(p)) = (vtu_dir.as_ref(), pvd_slot.as_mut()) {
                    let mut w = sonium_xem::io::vtu::VtuWriter::new(mesh.as_ref());
                    w.add_point_scalar_complex("pressure", solution.as_slice());
                    let fname = format!("fem_{}_f{:06.1}Hz.vtu", safe_names[src_idx], freq);
                    let _ = w.write(dir.join(&fname));
                    p.push(freq, fname);
                }

                *prev_sol = Some(solution.clone());

                SourceStats {
                    iterations: result.iterations,
                    residual: result.residual,
                    rhs_time,
                    solve_time,
                    converged: result.converged,
                    failed_solution: None,
                    accepted_solution: Some(solution),
                }
            };
            if parallel_sources {
                simulation
                    .sources
                    .par_iter()
                    .zip(pressures.par_iter_mut())
                    .zip(prev_solutions.par_iter_mut())
                    .zip(pvds.par_iter_mut())
                    .zip(recycled_per_source.into_par_iter())
                    .zip(rhs_buffers.par_iter_mut())
                    .enumerate()
                    .map(&solve_source)
                    .collect()
            } else {
                simulation
                    .sources
                    .iter()
                    .zip(pressures.iter_mut())
                    .zip(prev_solutions.iter_mut())
                    .zip(pvds.iter_mut())
                    .zip(recycled_per_source)
                    .zip(rhs_buffers.iter_mut())
                    .enumerate()
                    .map(solve_source)
                    .collect()
            }
        };

        if let Some(cancellation) = cancellation {
            if let Some(cursor) = schedule_cursor.as_mut() {
                cursor.poll_cancellation(cancellation)?;
            }
            ensure_not_cancelled(cancellation)?;
        }

        // Retry pass: any source that failed in parallel gets re-solved
        // serially with the recycler cleared and disabled for this freq —
        // a stale GCRO-DR subspace at a dense modal frequency can inject
        // directions that GMRES has to undo every restart, so falling back
        // to pure warm-start (None) is what we know converges. The freshly
        // built recycler will repopulate from this solve onward.
        let mut stats = stats;
        let failed_indices: Vec<usize> = stats
            .iter()
            .enumerate()
            .filter(|(_, s)| !s.converged)
            .map(|(i, _)| i)
            .collect();
        let retry_count = failed_indices.len();
        let direct_strong_fallback =
            !failed_indices.is_empty() && recycle_subspace_size == 0 && must_rebuild;
        let mut fallback_stage = if failed_indices.is_empty() {
            0
        } else if direct_strong_fallback {
            3
        } else {
            2
        };
        // A failed solve invalidates the amortised preconditioner assumption.
        // Reassemble P at the exact current frequency and rebuild it once for
        // all failed sources before retrying.  Previously the retry cleared
        // GCRO-DR but silently reused a factorisation up to N-1 frequencies
        // old, which is precisely least reliable near a moving modal pole.
        if !failed_indices.is_empty() {
            let rebuild_start = Instant::now();
            let p_shift = mesh_config.shifted_laplacian_shift.value(k);
            let p_boundary_coeffs = geometric_schwarz_coefficients(preconditioner, k);
            assembler.assemble_helmholtz_and_shift_with_preconditioner_boundaries_into(
                k_complex,
                &boundary_coeffs,
                p_shift,
                &p_boundary_coeffs,
                &mut csr,
                &mut p_matrix,
            );
            matrix_time += rebuild_start.elapsed();
            let precond_start = Instant::now();
            cached_precond = Some(build_preconditioner(
                &p_matrix,
                preconditioner,
                &ilut_config,
                k,
                geometric_schwarz
                    .as_ref()
                    .map(|transmission| transmission.partitions.as_slice()),
            ));
            precond_time += precond_start.elapsed();
            preconditioner_age = 0;
            rebuild_reason = "convergence-failure".to_string();
        }
        let strong_config = IlutConfig {
            drop_tolerance: 1e-6,
            fill_factor: 30,
            pivot_tolerance: 1e-12,
            pivoting: true,
        };
        let strong_gmres = GmresConfig {
            restart: gmres_config.restart.max(300),
            ..gmres_config.clone()
        };
        let direct_strong_precond = if direct_strong_fallback {
            let rebuild_start = Instant::now();
            let fallback_boundary_coeffs =
                geometric_schwarz_coefficients(FemPreconditionerKind::Ilut, k);
            assembler.assemble_helmholtz_and_shift_with_preconditioner_boundaries_into(
                k_complex,
                &boundary_coeffs,
                fallback_preconditioner_shift(k),
                &fallback_boundary_coeffs,
                &mut csr,
                &mut p_matrix,
            );
            matrix_time += rebuild_start.elapsed();
            let precond_start = Instant::now();
            let strong = FemPreconditioner::Ilut(IlutPreconditioner::from_csr_with_config(
                &p_matrix,
                &strong_config,
            ));
            precond_time += precond_start.elapsed();
            rebuild_reason = "strong-global-ilut".to_string();
            Some(strong)
        } else {
            None
        };
        for src_idx in failed_indices {
            let source = &simulation.sources[src_idx];
            if direct_strong_fallback {
                log::info!(
                    "FEM: retrying source {} at {:.1} Hz directly with strong global ILUT",
                    source.name,
                    freq,
                );
            } else {
                log::info!(
                    "FEM: retrying source {} at {:.1} Hz with cleared recycler and no recycling",
                    source.name,
                    freq,
                );
            }
            if let Some(subs) = recycled_subspaces.as_mut()
                && let Some(mut rebuilt) =
                    build_recycle_subspaces(recycle_subspace_size, mesh_config.recycler, 1)
            {
                subs[src_idx] = rebuilt
                    .pop()
                    .expect("build_recycle_subspaces with n_sources=1");
            }

            let rhs_start = Instant::now();
            assemble_rhs_from_basis_into(
                &rhs_bases[src_idx],
                source,
                freq,
                &mut rhs_buffers[src_idx],
            );
            let rhs_time_retry = rhs_start.elapsed();

            let solve_start = Instant::now();
            // None disables the recycler for this retry — the rebuilt
            // subspace above is preserved unchanged and will be filled
            // by the next frequency's solve.
            let retry_precond = direct_strong_precond.as_ref().unwrap_or_else(|| {
                cached_precond
                    .as_ref()
                    .expect("failed-source retry rebuilt the preconditioner")
            });
            let retry_gmres = if direct_strong_fallback {
                &strong_gmres
            } else {
                &gmres_config
            };
            let mut result = if let Some(cancellation) = cancellation {
                match solve_frequency_system_with_abort(
                    &csr,
                    retry_precond,
                    &rhs_buffers[src_idx],
                    retry_initial_guess(
                        stats[src_idx].failed_solution.as_deref(),
                        prev_solutions[src_idx].as_deref(),
                    ),
                    retry_gmres,
                    || cancellation.is_cancelled(),
                ) {
                    Ok(result) => result,
                    Err(error) if cancellation.is_cancelled() => {
                        cancellation.cancel(error.clone());
                        if let Some(cursor) = schedule_cursor.as_mut() {
                            cursor.poll_cancellation(cancellation)?;
                        }
                        return Err(anyhow::Error::msg(error));
                    }
                    Err(_error) => solve_frequency_system(
                        &csr,
                        retry_precond,
                        &rhs_buffers[src_idx],
                        retry_initial_guess(
                            stats[src_idx].failed_solution.as_deref(),
                            prev_solutions[src_idx].as_deref(),
                        ),
                        None,
                        retry_gmres,
                    ),
                }
            } else {
                solve_frequency_system(
                    &csr,
                    retry_precond,
                    &rhs_buffers[src_idx],
                    retry_initial_guess(
                        stats[src_idx].failed_solution.as_deref(),
                        prev_solutions[src_idx].as_deref(),
                    ),
                    None,
                    retry_gmres,
                )
            };
            if !result.converged && direct_strong_fallback {
                fallback_stage = 4;
                log::warn!(
                    "FEM strong-ILUT GMRES exhausted for source {} freq {:.1} Hz: res={:.2e}; trying bounded BiCGSTAB (max {} iterations)",
                    source.name,
                    freq,
                    result.residual,
                    BICGSTAB_FALLBACK_MAX_ITERATIONS,
                );
                let bicgstab = solve_frequency_system_bicgstab(
                    &csr,
                    direct_strong_precond
                        .as_ref()
                        .expect("direct strong fallback built the preconditioner"),
                    &rhs_buffers[src_idx],
                    Some(&result.x),
                    gmres_config.tolerance,
                );
                let iterations = result.iterations + bicgstab.iterations;
                result = GmresSolution {
                    iterations,
                    ..bicgstab
                };
            }

            if !result.converged && !direct_strong_fallback {
                fallback_stage = 3;
                log::warn!(
                    "FEM solve failed for source {} freq {:.1} Hz after exact-frequency rebuild: iters={} res={:.2e}; trying strong global ILUT",
                    source.name,
                    freq,
                    result.iterations,
                    result.residual,
                );
                let fallback_boundary_coeffs =
                    geometric_schwarz_coefficients(FemPreconditionerKind::Ilut, k);
                assembler.assemble_helmholtz_and_shift_with_preconditioner_boundaries_into(
                    k_complex,
                    &boundary_coeffs,
                    fallback_preconditioner_shift(k),
                    &fallback_boundary_coeffs,
                    &mut csr,
                    &mut p_matrix,
                );
                let strong_precond = FemPreconditioner::Ilut(
                    IlutPreconditioner::from_csr_with_config(&p_matrix, &strong_config),
                );
                let strong_result = if let Some(cancellation) = cancellation {
                    match solve_frequency_system_with_abort(
                        &csr,
                        &strong_precond,
                        &rhs_buffers[src_idx],
                        Some(&result.x),
                        &strong_gmres,
                        || cancellation.is_cancelled(),
                    ) {
                        Ok(result) => result,
                        Err(error) if cancellation.is_cancelled() => {
                            cancellation.cancel(error.clone());
                            if let Some(cursor) = schedule_cursor.as_mut() {
                                cursor.poll_cancellation(cancellation)?;
                            }
                            return Err(anyhow::Error::msg(error));
                        }
                        Err(_error) => solve_frequency_system(
                            &csr,
                            &strong_precond,
                            &rhs_buffers[src_idx],
                            Some(&result.x),
                            None,
                            &strong_gmres,
                        ),
                    }
                } else {
                    solve_frequency_system(
                        &csr,
                        &strong_precond,
                        &rhs_buffers[src_idx],
                        Some(&result.x),
                        None,
                        &strong_gmres,
                    )
                };
                result.iterations += strong_result.iterations;
                result = GmresSolution {
                    iterations: result.iterations,
                    ..strong_result
                };
            }

            let solve_time_retry = solve_start.elapsed();

            if !result.converged {
                log::error!(
                    "FEM solve failed for source {} freq {:.1} Hz after fallback ladder: iters={} true_res={:.2e}",
                    source.name,
                    freq,
                    result.iterations,
                    result.residual,
                );
                anyhow::bail!(
                    "FEM convergence failure at {:.1} Hz for source '{}': cached solve, exact-frequency rebuild, and strong ILUT fallback exhausted; true relative residual={:.2e}",
                    freq,
                    source.name,
                    result.residual,
                );
            }
            log::info!(
                "FEM: retry succeeded for source {} freq {:.1} Hz: iters={} res={:.2e}",
                source.name,
                freq,
                result.iterations,
                result.residual,
            );

            let solution = result.x;
            let mut lp_pressures =
                vec![Complex64::new(0.0, 0.0); simulation.listening_positions.len()];
            for (lp_idx, interp) in lp_interpolations.iter().enumerate() {
                lp_pressures[lp_idx] = evaluate_listener_interpolation(&solution, interp);
            }
            store_listener_pressures(
                &simulation.listening_positions,
                &lp_pressures,
                source,
                freq,
                &mut pressures[src_idx],
                freq_idx,
            );
            if let Some(dir) = vtu_dir.as_ref()
                && let Some(p) = pvds[src_idx].as_mut()
            {
                let mut w = sonium_xem::io::vtu::VtuWriter::new(mesh.as_ref());
                w.add_point_scalar_complex("pressure", solution.as_slice());
                let fname = format!("fem_{}_f{:06.1}Hz.vtu", safe_names[src_idx], freq);
                let _ = w.write(dir.join(&fname));
                p.push(freq, fname);
            }
            prev_solutions[src_idx] = Some(solution.clone());

            stats[src_idx] = SourceStats {
                iterations: stats[src_idx].iterations + result.iterations,
                residual: result.residual,
                rhs_time: stats[src_idx].rhs_time + rhs_time_retry,
                solve_time: stats[src_idx].solve_time + solve_time_retry,
                converged: true,
                failed_solution: None,
                accepted_solution: Some(solution),
            };
        }
        if let Some(nodal_pressures) = nodal_pressures.as_mut() {
            for (source_index, stats) in stats.iter().enumerate() {
                let solution = stats
                    .accepted_solution
                    .as_ref()
                    .expect("every converged FEM source has an accepted nodal solution");
                nodal_pressures[source_index][freq_idx].clone_from(solution);
            }
        }
        let mut operator_work = FemOperatorWorkEvidence {
            source_work: 0.0,
            volume_damping_work: 0.0,
            boundary_work: 0.0,
            balance_residual: 0.0,
        };
        let mut boundary_power_by_tag = BTreeMap::new();
        for (source_index, source_stats) in stats.iter().enumerate() {
            let solution = source_stats.accepted_solution.as_ref().ok_or_else(|| {
                anyhow::anyhow!(
                    "FEM source {source_index} has no accepted solution for operator-work evidence"
                )
            })?;
            let sample = fem_operator_work_evidence(
                &assembler,
                k_complex,
                &boundary_coeffs,
                &rhs_buffers[source_index],
                solution,
            )
            .map_err(anyhow::Error::msg)?;
            operator_work.source_work += sample.source_work;
            operator_work.volume_damping_work += sample.volume_damping_work;
            operator_work.boundary_work += sample.boundary_work;
            operator_work.balance_residual += sample.balance_residual;
            let flux = fem_boundary_flux_evidence(
                &assembler,
                &boundary_coeffs,
                freq,
                AIR_DENSITY,
                solution,
            )
            .map_err(anyhow::Error::msg)?;
            for sample in flux.samples {
                *boundary_power_by_tag
                    .entry(sample.boundary_tag)
                    .or_insert(0.0) += sample.active_power_w;
            }
        }
        operator_work.validate().map_err(anyhow::Error::msg)?;
        let physical_power =
            FemPhysicalPowerEvidence::from_operator_work(&operator_work, freq, AIR_DENSITY)
                .map_err(anyhow::Error::msg)?;
        let boundary_flux = FemBoundaryFluxEvidence::from_tagged_powers(boundary_power_by_tag)
            .map_err(anyhow::Error::msg)?;
        let rhs_time: Duration = stats.iter().map(|s| s.rhs_time).sum();
        let solve_time: Duration = stats.iter().map(|s| s.solve_time).sum();
        let total_iterations: usize = stats.iter().map(|s| s.iterations).sum();
        let max_residual: f64 = stats.iter().map(|s| s.residual).fold(0.0f64, f64::max);
        diagnostics.record_frequency(FemFrequencyStats {
            block_solve: Default::default(),
            frequency_hz: freq,
            symmetry_mode: None,
            matrix_ms: duration_ms(matrix_time),
            preconditioner_ms: duration_ms(precond_time),
            rhs_ms: duration_ms(rhs_time),
            solve_ms: duration_ms(solve_time),
            iterations: total_iterations,
            inner_iterations: 0,
            retries: retry_count,
            preconditioner_age,
            preconditioner_rebuild_reason: rebuild_reason,
            fallback_stage,
            max_residual,
            converged: true,
            operator_work: Some(operator_work),
            physical_power: Some(physical_power),
            boundary_flux: Some(boundary_flux),
            transfer_stats: None,
            allocation_operations: 0,
            allocation_high_water_bytes: 0,
            synchronization_calls: 0,
        });
        force_preconditioner_rebuild = iteration_spike(total_iterations, &recent_iterations);
        recent_iterations.push(total_iterations);

        if should_log_frequency(freq_idx, n_freqs) {
            log::info!(
                "FEM: frequency {}/{} ({:.1} Hz) done in {}: matrix={}, precond={}, RHS_sum={}, solve_sum={}, total_iters={}, max_res={:.2e}",
                freq_idx + 1,
                n_freqs,
                freq,
                fmt_duration(freq_start.elapsed()),
                fmt_duration(matrix_time),
                fmt_duration(precond_time),
                fmt_duration(rhs_time),
                fmt_duration(solve_time),
                total_iterations,
                max_residual,
            );
        } else {
            log::debug!(
                "FEM: frequency {}/{} ({:.1} Hz) done in {}: matrix={}, precond={}, RHS_sum={}, solve_sum={}, total_iters={}, max_res={:.2e}",
                freq_idx + 1,
                n_freqs,
                freq,
                fmt_duration(freq_start.elapsed()),
                fmt_duration(matrix_time),
                fmt_duration(precond_time),
                fmt_duration(rhs_time),
                fmt_duration(solve_time),
                total_iterations,
                max_residual,
            );
        }

        if let Some(cursor) = schedule_cursor.as_mut() {
            cursor.commit_frequency(freq_idx)?;
            if let Some(on_commit) = on_frequency_commit.as_deref_mut() {
                on_commit(cursor.checkpoint, freq_idx)?;
            }
        }
    }

    if let Some(cursor) = schedule_cursor {
        cursor.complete(cancellation)?;
    }

    for p in pvds.into_iter().flatten() {
        let _ = p.finish();
    }

    let output = SimulationOutput::solved(
        simulation.frequencies.clone(),
        pressures,
        simulation.sources.iter().map(|s| s.name.clone()).collect(),
    );
    let field = nodal_pressures.map(|pressures| FemNodalField {
        mesh: mesh.as_ref().clone(),
        frequencies: simulation.frequencies.clone(),
        source_names: simulation.sources.iter().map(|s| s.name.clone()).collect(),
        listener_positions: simulation.listening_positions.clone(),
        pressures,
    });
    Ok((output, field, diagnostics))
}

fn ensure_not_cancelled(cancellation: &FemRunCancellation) -> Result<()> {
    if cancellation.is_cancelled() {
        let reason = cancellation
            .first_error()
            .unwrap_or_else(|| "cancelled cooperatively".to_string());
        anyhow::bail!("FEM run cancelled: {reason}");
    }
    Ok(())
}

pub(super) fn run_fem_symmetric_report(
    simulation: &RoomSimulation,
    symmetry: &SymmetryConfig,
    mesh_config: &FemMeshConfig,
) -> Result<(SimulationOutput, FemRunDiagnostics)> {
    anyhow::ensure!(
        !simulation.frequencies.is_empty(),
        "FEM solve requires at least one frequency"
    );
    let (width, depth, height) = match &simulation.room {
        RoomGeometry::Rectangular(r) => (r.width, r.depth, r.height),
        RoomGeometry::LShaped(_) => unreachable!("symmetry requires rectangular room"),
    };

    // For image-source mirroring we want the *physical* walls of the full room
    // — never the symmetry cut planes (those are handled per parity at the
    // matrix level). A positive image across a cut plane would corrupt the
    // odd-mode RHS, so we deliberately ignore the half-domain mesh's AABB
    // here. Sources mapped into the half-domain that lie far from the full
    // room's opposite-side walls produce images that the per-element cutoff
    // filter rejects, so the cost is negligible.
    let image_walls_aabb: ([f64; 3], [f64; 3]) = ([0.0, 0.0, 0.0], [width, depth, height]);

    let max_freq = simulation
        .frequencies
        .iter()
        .cloned()
        .fold(f64::NEG_INFINITY, f64::max);
    let min_wavelength = simulation.speed_of_sound / max_freq;
    let elements_per_meter = (mesh_config.elements_per_wavelength / min_wavelength).ceil() as usize;

    log::info!(
        "FEM symmetric: building mesh for max_freq={:.0} Hz, grading {:.1}x",
        max_freq,
        mesh_config.grading_factor,
    );
    let mesh_start = Instant::now();
    let mesh = cached_room_mesh(simulation, elements_per_meter, symmetry, mesh_config);
    log::info!(
        "FEM symmetric mesh: {} nodes, {} elements (fine spacing {} elem/m, {}x reduction, grading {:.1}x, radius {:.2} m) built in {}",
        mesh.num_nodes(),
        mesh.num_elements(),
        elements_per_meter,
        symmetry.reduction_factor(),
        mesh_config.grading_factor,
        mesh_config.fine_radius,
        fmt_duration(mesh_start.elapsed()),
    );

    // Assemble frequency-independent matrices once on the reduced mesh
    log::info!("FEM symmetric: assembling frequency-independent matrices");
    let assembly_start = Instant::now();
    let stiffness = assemble_stiffness(&mesh, PolynomialDegree::P1);
    let mass = assemble_mass(&mesh, PolynomialDegree::P1);

    // Physical boundary mass matrices (not symmetry planes)
    let phys_markers = [
        MARKER_FLOOR,
        MARKER_CEILING,
        MARKER_FRONT,
        MARKER_BACK,
        MARKER_LEFT,
        MARKER_RIGHT,
    ];
    let mut boundary_matrices = Vec::new();
    for &marker in &phys_markers {
        let b_mass = assemble_boundary_mass(&mesh, PolynomialDegree::P1, marker);
        if b_mass.nnz() > 0 {
            boundary_matrices.push((marker as usize, b_mass));
        }
    }
    let geometric_schwarz = append_geometric_schwarz_boundary_matrices(
        &mesh,
        mesh_config.preconditioner,
        &mut boundary_matrices,
    );
    if let Some(transmission) = &geometric_schwarz {
        log::info!(
            "FEM symmetric: added geometry-exact {} interface terms on {} faces across {} subdomains",
            mesh_config.preconditioner,
            transmission.face_count,
            transmission.partitions.len(),
        );
    }
    log::info!(
        "FEM symmetric: assembled K nnz={}, M nnz={}, {} boundary matrices in {}",
        stiffness.nnz(),
        mass.nnz(),
        boundary_matrices.len(),
        fmt_duration(assembly_start.elapsed()),
    );

    let resolved_boundaries = resolve_boundaries(simulation)?;

    // Collect Dirichlet node sets for each symmetry plane
    let sym_x_nodes: HashSet<usize> = if symmetry.has_x() {
        collect_boundary_nodes(&mesh, MARKER_SYM_X)
    } else {
        HashSet::new()
    };
    let sym_y_nodes: HashSet<usize> = if symmetry.has_y() {
        collect_boundary_nodes(&mesh, MARKER_SYM_Y)
    } else {
        HashSet::new()
    };

    // Build one HelmholtzAssembler per mode.
    // Mode 0 = even on all planes (Neumann everywhere → no Dirichlet).
    // For odd modes, apply Dirichlet on the relevant cut planes.
    let num_modes = symmetry.num_modes();
    let mut assemblers: Vec<HelmholtzAssembler> = Vec::with_capacity(num_modes);
    for mode_idx in 0..num_modes {
        let parity = ModeParity::new(mode_idx, symmetry.planes.len());
        let mut asm = HelmholtzAssembler::from_matrices(&stiffness, &mass, &boundary_matrices);

        let mut dirichlet_nodes = HashSet::new();
        for (plane_idx, plane) in symmetry.planes.iter().enumerate() {
            if parity.is_odd(plane_idx) {
                match plane {
                    SymmetryPlane::X => dirichlet_nodes.extend(&sym_x_nodes),
                    SymmetryPlane::Y => dirichlet_nodes.extend(&sym_y_nodes),
                }
            }
        }
        if !dirichlet_nodes.is_empty() {
            asm.apply_dirichlet_nodes(&dirichlet_nodes);
        }
        assemblers.push(asm);
    }

    // Map listening positions to the reduced domain
    let mapped_lps: Vec<(Point3D, Vec<bool>)> = simulation
        .listening_positions
        .iter()
        .map(|lp| map_to_reduced_domain(*lp, symmetry, width, depth))
        .collect();

    // Pre-locate elements for mapped LPs. Sequential outer iteration —
    // see the matching note in `run_fem_full`; the inner element scan is
    // already parallel and the LP count is small.
    let lp_elements: Vec<Option<usize>> = mapped_lps
        .iter()
        .map(|(p, _)| find_containing_element_parallel(&mesh, *p))
        .collect();
    let mapped_lp_points: Vec<Point3D> = mapped_lps.iter().map(|(p, _)| *p).collect();
    let (lp_interpolations, listener_fallbacks) =
        build_listener_interpolations(&mesh, &mapped_lp_points, &lp_elements);
    if listener_fallbacks > 0 {
        log::warn!(
            "FEM symmetric: {listener_fallbacks} of {} listening positions fell back to nearest-node interpolation",
            lp_elements.len()
        );
    }

    let gmres_config = gmres_config(mesh_config);
    let ilut_config = IlutConfig {
        // 1e-5 (vs the older 1e-4) keeps more of the Helmholtz operator's
        // off-diagonal coupling. For Complex64 indefinite systems the dropped
        // entries accumulate and visibly slow GMRES convergence; this is
        // small enough not to noticeably grow fill but tight enough to keep
        // iteration counts stable across the frequency sweep.
        drop_tolerance: 1e-5,
        fill_factor: 20,
        pivot_tolerance: 1e-10,
        pivoting: true,
    };
    let preconditioner = mesh_config.preconditioner;
    let recycle_subspace_size = effective_recycle_subspace_size(mesh_config);
    let gmres_mode = if preconditioner == FemPreconditionerKind::Amg {
        "FGMRES".to_string()
    } else {
        gmres_mode_label(recycle_subspace_size, mesh_config.recycler)
    };

    let n_sources = simulation.sources.len();
    let n_lps = simulation.listening_positions.len();
    let n_freqs = simulation.frequencies.len();
    let mut diagnostics = FemRunDiagnostics::new("cpu-symmetric", mesh_config);
    diagnostics.listener_interpolation_fallbacks = listener_fallbacks;
    diagnostics.mark_reduced_domain_physical_evidence_unavailable();

    log::info!(
        "FEM symmetric: using shifted-Laplacian {} preconditioner, shift {}, and {}",
        preconditioner,
        mesh_config.shifted_laplacian_shift,
        gmres_mode,
    );

    // Map each source to the half-domain and record which planes were mirrored.
    // Mirror pairs map to the same position — we solve once and reconstruct both.
    let src_mapped: Vec<(Point3D, Vec<bool>)> = simulation
        .sources
        .iter()
        .map(|s| map_to_reduced_domain(s.position, symmetry, width, depth))
        .collect();

    // Mirror orientation AND directivity pattern across every plane the source
    // was reflected through. The parity decomposition reconstructs the
    // full-room field from image sources, and an image source only reproduces
    // the real mirror partner if its radiation pattern is the mirror image of
    // the original — mirroring the position alone would leave a directional
    // source at x=2.2 pointing −x mapped to x=0.8 *still* pointing −x
    // (toward the cut plane instead of away from it), corrupting every mode.
    let mapped_sources: Vec<Source> = simulation
        .sources
        .iter()
        .enumerate()
        .map(|(i, s)| {
            let mut mapped = s.clone();
            mapped.position = src_mapped[i].0;
            let mirrored = &src_mapped[i].1;
            for (&plane, &was_mirrored) in symmetry.planes.iter().zip(mirrored.iter()) {
                if was_mirrored {
                    match plane {
                        SymmetryPlane::X => mapped.orientation.x = -mapped.orientation.x,
                        SymmetryPlane::Y => mapped.orientation.y = -mapped.orientation.y,
                    }
                    mapped.directivity = mapped.directivity.mirrored();
                }
            }
            mapped
        })
        .collect();

    // Dedup: sources whose *mapped* forms are acoustically identical share
    // solutions. primary_for[i] = index of the first equivalent source.
    //
    // Equivalence requires the same mapped position plus identical amplitude,
    // crossover, directivity, and (for directional sources) orientation.
    // This is what makes the dedup provably correct: `detect_symmetry`
    // only accepts mirror partners whose orientation is the plane-mirror of
    // the original, so after the mapping above a Classical or mirror-symmetric
    // Grid pair reduces to the SAME mapped source and still shares one solve.
    // An asymmetric Grid pair maps to two different patterns and is solved
    // separately. Isotropic sources ignore orientation entirely.
    //
    // O(n) HashMap-based dedup. Positions are quantised at 1e-8 m (10 nm)
    // before hashing — well below any meaningful acoustic length scale, so
    // two sources that should be considered identical hash to the same
    // bucket. To absorb the rare case where two positions straddle a
    // bucket boundary (differ by e.g. 0.6e-8 across a quantum), we also
    // probe the neighbouring 3-D buckets. Each bucket holds every primary
    // that hashed to it; candidates must also pass the acoustic-equivalence
    // check above.
    let eps_pos = 1e-8_f64;
    let inv_eps = 1.0 / eps_pos;
    let quantise = |p: &Point3D| -> [i64; 3] {
        [
            (p.x * inv_eps).round() as i64,
            (p.y * inv_eps).round() as i64,
            (p.z * inv_eps).round() as i64,
        ]
    };
    let equivalent = |i: usize, j: usize| -> bool {
        let a = &mapped_sources[i];
        let b = &mapped_sources[j];
        sonium_xem::symmetry::sources_match(a, b)
            && (a.directivity.is_isotropic()
                || ((a.orientation.x - b.orientation.x).abs() < 1e-9
                    && (a.orientation.y - b.orientation.y).abs() < 1e-9
                    && (a.orientation.z - b.orientation.z).abs() < 1e-9))
    };
    let position_close = |i: usize, j: usize| -> bool {
        let pi = &src_mapped[i].0;
        let pj = &src_mapped[j].0;
        (pi.x - pj.x).abs() < eps_pos
            && (pi.y - pj.y).abs() < eps_pos
            && (pi.z - pj.z).abs() < eps_pos
    };
    let mut bucket_to_idx: HashMap<[i64; 3], Vec<usize>> = HashMap::with_capacity(n_sources);
    let mut primary_for: Vec<usize> = Vec::with_capacity(n_sources);
    for (i, mapped_source) in src_mapped.iter().enumerate() {
        let key = quantise(&mapped_source.0);
        let mut hit: Option<usize> = bucket_to_idx.get(&key).and_then(|candidates| {
            candidates
                .iter()
                .find(|&&j| position_close(i, j) && equivalent(i, j))
                .copied()
        });
        if hit.is_none() {
            // Tiebreaker: probe the 26 neighbouring buckets (excluding
            // self) for an entry within the same `eps_pos` tolerance.
            'probe: for dx in -1..=1 {
                for dy in -1..=1 {
                    for dz in -1..=1 {
                        if dx == 0 && dy == 0 && dz == 0 {
                            continue;
                        }
                        let nkey = [key[0] + dx, key[1] + dy, key[2] + dz];
                        if let Some(candidates) = bucket_to_idx.get(&nkey)
                            && let Some(&j) = candidates
                                .iter()
                                .find(|&&j| position_close(i, j) && equivalent(i, j))
                        {
                            hit = Some(j);
                            break 'probe;
                        }
                    }
                }
            }
        }
        let primary = hit.unwrap_or(i);
        if primary == i {
            bucket_to_idx.entry(key).or_default().push(i);
        }
        primary_for.push(primary);
    }

    let primary_indices: Vec<usize> = (0..n_sources).filter(|&i| primary_for[i] == i).collect();
    let primary_count = primary_indices.len();
    let mut primary_sources = Vec::with_capacity(primary_count);
    let mut primary_rhs_bases = Vec::with_capacity(primary_count);
    for &src_idx in &primary_indices {
        let mapped_source = mapped_sources[src_idx].clone();
        primary_rhs_bases.push(build_source_rhs_basis_for_model(
            &mesh,
            &mapped_source,
            image_walls_aabb,
            mesh_config.source_model,
        )?);
        primary_sources.push(mapped_source);
    }

    log::info!(
        "FEM symmetric: solving {} primary sources across {} modes; sharing one matrix/preconditioner per mode/frequency",
        primary_count,
        num_modes,
    );

    // Each mode only needs listener pressures for reconstruction. Keep the
    // previous full nodal solution for warm-starting, but do not retain every
    // nodal solution across the whole sweep.
    let cancellation = SymmetryCancellation::default();
    let mode_outputs_result: Result<Vec<ModeSolveReport>> = (0..num_modes)
        .into_par_iter()
        .map(|mode_idx| -> Result<ModeSolveReport> {
            if cancellation.is_cancelled() {
                anyhow::bail!("FEM symmetric mode {mode_idx} cancelled after sibling failure");
            }
            let parity = ModeParity::new(mode_idx, symmetry.planes.len());
            let assembler = &assemblers[mode_idx];
            let rebuild_every = mesh_config.rebuild_precond_every.max(1);
            let recycle_reset_every = mesh_config.recycle_reset_every;
            let mut cached_precond: Option<FemPreconditioner> = None;
            let mut preconditioner_age = 0usize;
            let mut force_preconditioner_rebuild = false;
            let mut recent_iterations = Vec::new();
            let mut csr = assembler.empty_matrix();
            let mut p_matrix = assembler.empty_matrix();
            let mut prev_solutions: Vec<Option<Vec<Complex64>>> = vec![None; primary_count];
            let mut recycled_subspaces =
                build_recycle_subspaces(recycle_subspace_size, mesh_config.recycler, primary_count);
            let mut rhs_array = vec![Complex64::new(0.0, 0.0); mesh.num_nodes()];
            let mut this_mode: Vec<Vec<Vec<Complex64>>> =
                vec![vec![vec![Complex64::new(0.0, 0.0); n_freqs]; n_lps]; primary_count];
            let mut mode_stats = Vec::new();

            let skip_source: Vec<bool> = primary_indices
                .iter()
                .map(|&src_idx| {
                    symmetry.planes.iter().enumerate().any(|(pi, plane)| {
                        if !parity.is_odd(pi) {
                            return false;
                        }
                        let eps = 1e-6;
                        match plane {
                            SymmetryPlane::X => {
                                (simulation.sources[src_idx].position.x - width / 2.0).abs() < eps
                            }
                            SymmetryPlane::Y => {
                                (simulation.sources[src_idx].position.y - depth / 2.0).abs() < eps
                            }
                        }
                    })
                })
                .collect();

            if skip_source.iter().all(|skip| *skip) {
                return Ok((this_mode, mode_stats));
            }

            for (freq_idx, &freq) in simulation.frequencies.iter().enumerate() {
                if cancellation.is_cancelled() {
                    anyhow::bail!("FEM symmetric mode {mode_idx} cancelled after sibling failure");
                }
                let freq_start = Instant::now();
                let k = simulation.wavenumber(freq);
                let k_complex = complex_wavenumber(k, freq, mesh_config.modal_damping_ratio);

                if recycle_reset_every > 0
                    && freq_idx > 0
                    && freq_idx.is_multiple_of(recycle_reset_every)
                    && recycled_subspaces.is_some()
                {
                    log::debug!(
                        "FEM symmetric: resetting recycled subspaces at mode={} freq {}/{} ({:.1} Hz)",
                        mode_idx,
                        freq_idx + 1,
                        n_freqs,
                        freq,
                    );
                    recycled_subspaces = build_recycle_subspaces(
                        recycle_subspace_size,
                        mesh_config.recycler,
                        primary_count,
                    );
                }

                if should_log_frequency(freq_idx, n_freqs) {
                    log::info!(
                        "FEM symmetric: mode={} frequency {}/{} ({:.1} Hz) started",
                        mode_idx,
                        freq_idx + 1,
                        n_freqs,
                        freq,
                    );
                } else {
                    log::debug!(
                        "FEM symmetric: mode={} frequency {}/{} ({:.1} Hz) started",
                        mode_idx,
                        freq_idx + 1,
                        n_freqs,
                        freq,
                    );
                }

                let matrix_start = Instant::now();
                let boundary_coeffs =
                    compute_boundary_coefficients(simulation, &resolved_boundaries, freq)?;
                let must_rebuild = cached_precond.is_none()
                    || freq_idx % rebuild_every == 0
                    || force_preconditioner_rebuild;
                let mut rebuild_reason = if cached_precond.is_none() {
                    "initial"
                } else if force_preconditioner_rebuild {
                    "iteration-spike"
                } else if freq_idx % rebuild_every == 0 {
                    "scheduled"
                } else {
                    "cached"
                }
                .to_string();
                let mut matrix_time;
                let mut precond_time;
                if must_rebuild {
                    let p_shift = mesh_config.shifted_laplacian_shift.value(k);
                    let p_boundary_coeffs = geometric_schwarz_coefficients(preconditioner, k);
                    assembler.assemble_helmholtz_and_shift_with_preconditioner_boundaries_into(
                        k_complex,
                        &boundary_coeffs,
                        p_shift,
                        &p_boundary_coeffs,
                        &mut csr,
                        &mut p_matrix,
                    );
                    matrix_time = matrix_start.elapsed();
                    log::debug!(
                        "FEM symmetric: building {} preconditioner for mode={} freq={:.1} Hz",
                        preconditioner,
                        mode_idx,
                        freq,
                    );
                    let precond_start = Instant::now();
                    cached_precond = Some(build_preconditioner(
                        &p_matrix,
                        preconditioner,
                        &ilut_config,
                        k,
                        geometric_schwarz
                            .as_ref()
                            .map(|transmission| transmission.partitions.as_slice()),
                    ));
                    precond_time = precond_start.elapsed();
                    preconditioner_age = 0;
                } else {
                    assembler.assemble_into(k_complex, &boundary_coeffs, &mut csr);
                    matrix_time = matrix_start.elapsed();
                    precond_time = Duration::ZERO;
                    preconditioner_age += 1;
                }
                let mut rhs_time_total = Duration::ZERO;
                let mut solve_time_total = Duration::ZERO;
                let mut total_iterations = 0usize;
                let mut max_residual = 0.0f64;
                let mut retry_count = 0usize;
                let mut fallback_stage = 0usize;
                let mut retry_precond_rebuilt = false;
                let direct_strong_fallback = recycle_subspace_size == 0 && must_rebuild;
                let strong_config = IlutConfig {
                    drop_tolerance: 1e-6,
                    fill_factor: 30,
                    pivot_tolerance: 1e-12,
                    pivoting: true,
                };
                let strong_gmres = GmresConfig {
                    restart: gmres_config.restart.max(300),
                    ..gmres_config.clone()
                };
                let mut strong_precond = None;

                for local_src_idx in 0..primary_count {
                    if skip_source[local_src_idx] {
                        continue;
                    }

                    let src_idx = primary_indices[local_src_idx];
                    let source = &primary_sources[local_src_idx];
                    let rhs_start = Instant::now();
                    assemble_rhs_from_basis_into(
                        &primary_rhs_bases[local_src_idx],
                        source,
                        freq,
                        &mut rhs_array,
                    );

                    // Zero RHS at Dirichlet nodes
                    for (pi, plane) in symmetry.planes.iter().enumerate() {
                        if parity.is_odd(pi) {
                            let nodes = match plane {
                                SymmetryPlane::X => &sym_x_nodes,
                                SymmetryPlane::Y => &sym_y_nodes,
                            };
                            for &n in nodes {
                                rhs_array[n] = Complex64::new(0.0, 0.0);
                            }
                        }
                    }
                    let rhs_time = rhs_start.elapsed();
                    rhs_time_total += rhs_time;

                    let recycled_subspace = recycled_subspaces
                        .as_mut()
                        .map(|subspaces| &mut subspaces[local_src_idx]);
                    let solve_start = Instant::now();
                    let first_precond = strong_precond.as_ref().unwrap_or_else(|| {
                        cached_precond
                            .as_ref()
                            .expect("rebuild path always populates cached_precond")
                    });
                    let first_gmres = if strong_precond.is_some() {
                        &strong_gmres
                    } else {
                        &gmres_config
                    };
                    let first_result = solve_frequency_system(
                        &csr,
                        first_precond,
                        &rhs_array,
                        prev_solutions[local_src_idx].as_deref(),
                        recycled_subspace,
                        first_gmres,
                    );

                    let result = if first_result.converged {
                        first_result
                    } else {
                        if cancellation.is_cancelled() {
                            anyhow::bail!(
                                "FEM symmetric mode {mode_idx} cancelled before retry at {freq:.1} Hz"
                            );
                        }
                        retry_count += 1;
                        fallback_stage = fallback_stage.max(if direct_strong_fallback { 3 } else { 2 });
                        if direct_strong_fallback && strong_precond.is_none() {
                            log::warn!(
                                "FEM symmetric solve failed first pass: src={} mode={} freq={:.1}: iters={} res={:.2e} (retrying directly with strong global ILUT)",
                                simulation.sources[src_idx].name,
                                mode_idx,
                                freq,
                                first_result.iterations,
                                first_result.residual,
                            );
                        } else {
                            log::warn!(
                                "FEM symmetric solve failed first pass: src={} mode={} freq={:.1}: iters={} res={:.2e} (retrying with cleared recycler)",
                                simulation.sources[src_idx].name,
                                mode_idx,
                                freq,
                                first_result.iterations,
                                first_result.residual,
                            );
                        }
                        if let Some(subspaces) = recycled_subspaces.as_mut()
                            && let Some(mut rebuilt) = build_recycle_subspaces(
                                recycle_subspace_size,
                                mesh_config.recycler,
                                1,
                            )
                        {
                            subspaces[local_src_idx] = rebuilt
                                .pop()
                                .expect("build_recycle_subspaces with n_sources=1");
                        }
                        if direct_strong_fallback && strong_precond.is_none() {
                            let rebuild_start = Instant::now();
                            let fallback_boundary_coeffs = geometric_schwarz_coefficients(
                                FemPreconditionerKind::Ilut,
                                k,
                            );
                            assembler.assemble_helmholtz_and_shift_with_preconditioner_boundaries_into(
                                k_complex,
                                &boundary_coeffs,
                                fallback_preconditioner_shift(k),
                                &fallback_boundary_coeffs,
                                &mut csr,
                                &mut p_matrix,
                            );
                            matrix_time += rebuild_start.elapsed();
                            let precond_start = Instant::now();
                            strong_precond = Some(FemPreconditioner::Ilut(
                                IlutPreconditioner::from_csr_with_config(
                                    &p_matrix,
                                    &strong_config,
                                ),
                            ));
                            precond_time += precond_start.elapsed();
                            rebuild_reason = "strong-global-ilut".to_string();
                        } else if !direct_strong_fallback && !retry_precond_rebuilt {
                            let rebuild_start = Instant::now();
                            let p_shift = mesh_config.shifted_laplacian_shift.value(k);
                            let p_boundary_coeffs =
                                geometric_schwarz_coefficients(preconditioner, k);
                            assembler.assemble_helmholtz_and_shift_with_preconditioner_boundaries_into(
                                k_complex,
                                &boundary_coeffs,
                                p_shift,
                                &p_boundary_coeffs,
                                &mut csr,
                                &mut p_matrix,
                            );
                            matrix_time += rebuild_start.elapsed();
                            let precond_start = Instant::now();
                            cached_precond = Some(build_preconditioner(
                                &p_matrix,
                                preconditioner,
                                &ilut_config,
                                k,
                                geometric_schwarz
                                    .as_ref()
                                    .map(|transmission| transmission.partitions.as_slice()),
                            ));
                            precond_time += precond_start.elapsed();
                            retry_precond_rebuilt = true;
                            preconditioner_age = 0;
                            rebuild_reason = "convergence-failure".to_string();
                        }
                        let mut retry_result = solve_frequency_system(
                            &csr,
                            strong_precond.as_ref().unwrap_or_else(|| {
                                cached_precond
                                    .as_ref()
                                    .expect("symmetric retry rebuilt the preconditioner")
                            }),
                            &rhs_array,
                            Some(&first_result.x),
                            None,
                            if direct_strong_fallback {
                                &strong_gmres
                            } else {
                                &gmres_config
                            },
                        );
                        if !retry_result.converged && direct_strong_fallback {
                            if cancellation.is_cancelled() {
                                anyhow::bail!(
                                    "FEM symmetric mode {mode_idx} cancelled before BiCGSTAB at {freq:.1} Hz"
                                );
                            }
                            fallback_stage = 4;
                            log::warn!(
                                "FEM symmetric strong-ILUT GMRES exhausted: src={} mode={} freq={:.1} res={:.2e}; trying bounded BiCGSTAB (max {} iterations)",
                                simulation.sources[src_idx].name,
                                mode_idx,
                                freq,
                                retry_result.residual,
                                BICGSTAB_FALLBACK_MAX_ITERATIONS,
                            );
                            let bicgstab = solve_frequency_system_bicgstab(
                                &csr,
                                strong_precond
                                    .as_ref()
                                    .expect("direct symmetric fallback built strong ILUT"),
                                &rhs_array,
                                Some(&retry_result.x),
                                gmres_config.tolerance,
                            );
                            let iterations = retry_result.iterations + bicgstab.iterations;
                            retry_result = GmresSolution {
                                iterations,
                                ..bicgstab
                            };
                        }
                        if !retry_result.converged && !direct_strong_fallback {
                            if cancellation.is_cancelled() {
                                anyhow::bail!(
                                    "FEM symmetric mode {mode_idx} cancelled before strong ILUT at {freq:.1} Hz"
                                );
                            }
                            fallback_stage = 3;
                            log::warn!(
                                "FEM symmetric exact-frequency retry failed: src={} mode={} freq={:.1}: true_res={:.2e}; trying strong global ILUT",
                                simulation.sources[src_idx].name,
                                mode_idx,
                                freq,
                                retry_result.residual,
                            );
                            let fallback_boundary_coeffs = geometric_schwarz_coefficients(
                                FemPreconditionerKind::Ilut,
                                k,
                            );
                            assembler.assemble_helmholtz_and_shift_with_preconditioner_boundaries_into(
                                k_complex,
                                &boundary_coeffs,
                                fallback_preconditioner_shift(k),
                                &fallback_boundary_coeffs,
                                &mut csr,
                                &mut p_matrix,
                            );
                            let strong_precond = FemPreconditioner::Ilut(
                                IlutPreconditioner::from_csr_with_config(
                                    &p_matrix,
                                    &strong_config,
                                ),
                            );
                            let strong_result = solve_frequency_system(
                                &csr,
                                &strong_precond,
                                &rhs_array,
                                Some(&retry_result.x),
                                None,
                                &strong_gmres,
                            );
                            if cancellation.is_cancelled() {
                                anyhow::bail!(
                                    "FEM symmetric mode {mode_idx} cancelled during strong ILUT at {freq:.1} Hz"
                                );
                            }
                            retry_result.iterations += strong_result.iterations;
                            retry_result = GmresSolution {
                                iterations: retry_result.iterations,
                                ..strong_result
                            };
                        }
                        retry_result.iterations += first_result.iterations;
                        if retry_result.converged {
                            log::info!(
                                "FEM symmetric retry succeeded: src={} mode={} freq={:.1}: iters={} res={:.2e}",
                                simulation.sources[src_idx].name,
                                mode_idx,
                                freq,
                                retry_result.iterations,
                                retry_result.residual,
                            );
                        }
                        retry_result
                    };
                    let solve_time = solve_start.elapsed();
                    solve_time_total += solve_time;
                    total_iterations += result.iterations;
                    max_residual = max_residual.max(result.residual);

                    if !result.converged {
                        let error = format!(
                            "FEM symmetric convergence failure at {:.1} Hz for source '{}' mode {}: cached solve, exact-frequency rebuild, and coercive global ILUT fallback exhausted; iterations={}; true relative residual={:.2e}",
                            freq,
                            simulation.sources[src_idx].name,
                            mode_idx,
                            result.iterations,
                            result.residual,
                        );
                        log::error!("{error}");
                        cancellation.cancel(error.clone());
                        anyhow::bail!(error);
                    }

                    let solution = result.x;
                    for (lp_idx, interp) in lp_interpolations.iter().enumerate() {
                        this_mode[local_src_idx][lp_idx][freq_idx] =
                            evaluate_listener_interpolation(&solution, interp);
                    }
                    prev_solutions[local_src_idx] = Some(solution);
                }
                mode_stats.push(FemFrequencyStats {
                    block_solve: Default::default(),
                    frequency_hz: freq,
                    symmetry_mode: Some(mode_idx),
                    matrix_ms: duration_ms(matrix_time),
                    preconditioner_ms: duration_ms(precond_time),
                    rhs_ms: duration_ms(rhs_time_total),
                    solve_ms: duration_ms(solve_time_total),
                    iterations: total_iterations,
                    inner_iterations: 0,
                    retries: retry_count,
                    preconditioner_age,
                    preconditioner_rebuild_reason: rebuild_reason,
                    fallback_stage,
                    max_residual,
                    converged: true,
                    operator_work: None,
                    physical_power: None,
                    boundary_flux: None,
                    transfer_stats: None,
                    allocation_operations: 0,
                    allocation_high_water_bytes: 0,
                    synchronization_calls: 0,
                });
                force_preconditioner_rebuild =
                    iteration_spike(total_iterations, &recent_iterations);
                recent_iterations.push(total_iterations);

                if should_log_frequency(freq_idx, n_freqs) {
                    log::info!(
                        "FEM symmetric: mode={} frequency {}/{} ({:.1} Hz) done in {}: matrix={}, precond={}, RHS_sum={}, solve_sum={}, total_iters={}, max_res={:.2e}",
                        mode_idx,
                        freq_idx + 1,
                        n_freqs,
                        freq,
                        fmt_duration(freq_start.elapsed()),
                        fmt_duration(matrix_time),
                        fmt_duration(precond_time),
                        fmt_duration(rhs_time_total),
                        fmt_duration(solve_time_total),
                        total_iterations,
                        max_residual,
                    );
                } else {
                    log::debug!(
                        "FEM symmetric: mode={} frequency {}/{} ({:.1} Hz) done in {}: matrix={}, precond={}, RHS_sum={}, solve_sum={}, total_iters={}, max_res={:.2e}",
                        mode_idx,
                        freq_idx + 1,
                        n_freqs,
                        freq,
                        fmt_duration(freq_start.elapsed()),
                        fmt_duration(matrix_time),
                        fmt_duration(precond_time),
                        fmt_duration(rhs_time_total),
                        fmt_duration(solve_time_total),
                        total_iterations,
                        max_residual,
                    );
                }
            }

            Ok((this_mode, mode_stats))
        })
        .collect();
    let mode_outputs = match mode_outputs_result {
        Ok(outputs) => outputs,
        Err(error) => {
            if let Some(first_error) = cancellation.first_error() {
                anyhow::bail!(first_error);
            }
            return Err(error);
        }
    };

    for (_, stats) in &mode_outputs {
        for stat in stats {
            diagnostics.record_frequency(stat.clone());
        }
    }

    let mut all_mode_pressures: HashMap<usize, Vec<Vec<Vec<Complex64>>>> = primary_indices
        .iter()
        .map(|&src_idx| (src_idx, Vec::with_capacity(num_modes)))
        .collect();
    for (mode_output, _) in mode_outputs {
        for (local_src_idx, listener_pressures) in mode_output.into_iter().enumerate() {
            all_mode_pressures
                .get_mut(&primary_indices[local_src_idx])
                .expect("primary source output slot exists")
                .push(listener_pressures);
        }
    }

    let mut pressures: Vec<Vec<Vec<Complex64>>> =
        vec![vec![vec![Complex64::new(0.0, 0.0); n_freqs]; n_lps]; n_sources];

    // Reconstruct each source from its primary's per-listener mode pressures.
    //
    // Physics: the even-mode Neumann BC mirrors the source, so the even
    // solution = p_src + p_mirror.  Decomposing:
    //   p_src   = (even + odd) / 2   (for source in the half-domain)
    //   p_mirror = (even - odd) / 2
    //
    // The odd-mode sign depends on whether the LP AND the source were
    // mirrored to reach the half-domain.  Per odd plane:
    //   sign *= -1  if  src_mirrored[i] XOR lp_mirrored[i]
    //
    // Sources on the symmetry plane have no mirror partner, only the even
    // mode contributes, and no 1/2 factor is needed.
    //
    // Parallelism: each (src_idx, lp_idx) writes to a disjoint
    // `pressures[src][lp][..]` slice and reads mode listener pressures and
    // mirror metadata immutably — embarrassingly parallel over sources.
    let n_modes = symmetry.planes.len();
    pressures
        .par_iter_mut()
        .enumerate()
        .for_each(|(src_idx, src_pressures)| {
            let primary = primary_for[src_idx];
            let mode_pressures = &all_mode_pressures[&primary];
            let (_, ref src_mirrored) = src_mapped[src_idx];

            let eps = 1e-6;
            let n_paired_planes = symmetry
                .planes
                .iter()
                .filter(|plane| {
                    let on_plane = match plane {
                        SymmetryPlane::X => {
                            (simulation.sources[src_idx].position.x - width / 2.0).abs() < eps
                        }
                        SymmetryPlane::Y => {
                            (simulation.sources[src_idx].position.y - depth / 2.0).abs() < eps
                        }
                    };
                    !on_plane
                })
                .count();
            let norm = 1.0 / (1u64 << n_paired_planes) as f64;
            for (lp_idx, (_, lp_mirrored)) in mapped_lps.iter().enumerate() {
                let combined: Vec<bool> = src_mirrored
                    .iter()
                    .zip(lp_mirrored.iter())
                    .map(|(&s, &l)| s ^ l)
                    .collect();

                let mode_signs: Vec<f64> = (0..mode_pressures.len())
                    .map(|m| ModeParity::new(m, n_modes).sign(&combined))
                    .collect();

                let dst = &mut src_pressures[lp_idx];
                for freq_idx in 0..simulation.frequencies.len() {
                    let mut total = Complex64::new(0.0, 0.0);
                    for (mode_idx, mode_lp_pressures) in mode_pressures.iter().enumerate() {
                        total += Complex64::new(mode_signs[mode_idx] * norm, 0.0)
                            * mode_lp_pressures[lp_idx][freq_idx];
                    }
                    dst[freq_idx] = total;
                }
            }
        });

    Ok((
        SimulationOutput::solved(
            simulation.frequencies.clone(),
            pressures,
            simulation.sources.iter().map(|s| s.name.clone()).collect(),
        ),
        diagnostics,
    ))
}
